222	static int esp32p4_sdmmc_interrupt(int irq, void *context, void *arg)
223	{
224	  struct esp32p4_sdmmc_state_s *state = arg;
225	  sdmmc_dev_t *hw = SDMMC_LL_GET_HW(0);
226	  uint32_t status;
227	  uint32_t idsts;
228	
229	  status = sdmmc_ll_get_intr_status(hw);
230	  sdmmc_ll_clear_interrupt(hw, status);
231	
232	  idsts = sdmmc_ll_get_idsts_interrupt_raw(hw);
233	  sdmmc_ll_clear_idsts_interrupt(hw, idsts);
234	
235	  state->pending |= status;
236	
237	  if (state->waitevents & status)
238	    {
239	      state->wkupevent = state->waitevents & status;
240	      nxsem_post(&state->sem);
241	    }
242	
243	  return OK;
244	}
