246	/* ========================================================================
247	 * 时钟控制（使用 LL 层）
248	 * ======================================================================== */
249	
250	static void esp32p4_sdmmc_set_clock(struct esp32p4_sdmmc_state_s *state,
251	                                    uint32_t freq_khz)
252	{
253	  sdmmc_dev_t *hw = SDMMC_LL_GET_HW(0);
254	  uint32_t div;
255	
256	  /* 计算分频：clk = 160MHz / div */
257	  div = (SDMMC_SRC_CLK_KHZ + freq_khz - 1) / freq_khz;
258	  if (div < 1)
259	    {
260	      div = 1;
261	    }
262	  if (div > 0xFF)
263	    {
264	      div = 0xFF;
265	    }
266	
267	  /* 1. 关闭 card clock */
268	  sdmmc_ll_enable_card_clock(hw, state->slot, false);
269	
270	  /* 2. 设置 DW 控制器内部分频 */
271	  sdmmc_ll_set_card_clock_div(hw, state->slot, div);
272	
273	  /* 3. 重新使能 card clock */
274	  sdmmc_ll_enable_card_clock(hw, state->slot, true);
275	
276	  state->freq_khz = SDMMC_SRC_CLK_KHZ / div;
277	  mcinfo("Slot %d clock: %lu kHz (div=%lu)\n",
278	         state->slot, (unsigned long)state->freq_khz, (unsigned long)div);
279	}
