281	/* ========================================================================
282	 * 控制器复位（使用 LL 层）
283	 * ======================================================================== */
284	
285	static void esp32p4_sdmmc_reset_controller(void)
286	{
287	  sdmmc_dev_t *hw = SDMMC_LL_GET_HW(0);
288	  uint32_t timeout;
289	
290	  /* DMA 复位 */
291	  sdmmc_ll_reset_dma(hw);
292	  timeout = 10000;
293	  while (!sdmmc_ll_is_dma_reset_done(hw))
294	    {
295	      if (--timeout == 0)
296	        {
297	          break;
298	        }
299	      up_udelay(10);
300	    }
301	
302	  /* FIFO 复位 */
303	  sdmmc_ll_reset_fifo(hw);
304	  timeout = 10000;
305	  while (!sdmmc_ll_is_fifo_reset_done(hw))
306	    {
307	      if (--timeout == 0)
308	        {
309	          break;
310	        }
311	      up_udelay(10);
312	    }
313	
314	  /* 控制器复位 */
315	  sdmmc_ll_reset_controller(hw);
316	  timeout = 10000;
317	  while (!sdmmc_ll_is_controller_reset_done(hw))
318	    {
319	      if (--timeout == 0)
320	        {
321	          break;
322	        }
323	      up_udelay(10);
324	    }
325	
326	  /* 清除中断 */
327	  sdmmc_ll_clear_interrupt(hw, 0xFFFFFFFF);
328	  sdmmc_ll_clear_idsts_interrupt(hw, 0xFFFFFFFF);
329	}
