346	/* ========================================================================
347	 * DMA 描述符设置
348	 * ======================================================================== */
349	
350	static void esp32p4_sdmmc_setup_dma(struct esp32p4_sdmmc_state_s *state,
351	                                    uint8_t *buffer, size_t nbytes, bool is_tx)
352	{
353	  size_t desc_idx = 0;
354	  size_t remaining = nbytes;
355	  uint8_t *buf_ptr = buffer;
356	
357	  while (remaining > 0 && desc_idx < SDMMC_DMA_DESC_NUM)
358	    {
359	      size_t chunk = remaining;
360	      if (chunk > 4096)
361	        {
362	          chunk = 4096;
363	        }
364	
365	      struct esp32p4_sdmmc_dmadesc_s *desc = &state->dma_desc[desc_idx];
366	
367	      desc->ctrl = (1U << 31) |  /* OWN */
368	                   (1U << 26) |  /* FS */
369	                   (1U << 25) |  /* LD */
370	                   (1U << 29) |  /* ER */
371	                   (chunk & 0x1FFF);
372	      desc->size = chunk;
373	      desc->buf_addr = (uint32_t)buf_ptr;
374	      desc->next_desc = 0;
375	
376	      buf_ptr += chunk;
377	      remaining -= chunk;
378	      desc_idx++;
379	    }
380	
381	  SDMMC_INV_DCACHE((uintptr_t)state->dma_desc,
382	                   (uintptr_t)state->dma_desc + sizeof(state->dma_desc));
383	
384	  if (!is_tx)
385	    {
386	      SDMMC_INV_DCACHE((uintptr_t)buffer, (uintptr_t)buffer + nbytes);
387	    }
388	  else
389	    {
390	      SDMMC_CLN_DCACHE((uintptr_t)buffer, (uintptr_t)buffer + nbytes);
391	    }
392	
393	  sdmmc_dev_t *hw = SDMMC_LL_GET_HW(0);
394	  sdmmc_ll_set_desc_addr(hw, (uint32_t)&state->dma_desc[0]);
395	}
