472	 * 命令发送（使用 sdmmc_hw_cmd_t）
473	 * ======================================================================== */
474	
475	static int esp32p4_sdmmc_sendcmd(struct sdio_dev_s *dev, uint32_t cmd,
476	                                 uint32_t arg)
477	{
478	  struct esp32p4_sdmmc_state_s *state = esp32p4_sdmmc_get_state(dev);
479	  sdmmc_dev_t *hw = SDMMC_LL_GET_HW(0);
480	  uint32_t cmdidx = cmd & MMCSD_CMDIDX_MASK;
481	  sdmmc_hw_cmd_t s_cmd;
482	  uint32_t timeout;
483	  int ret;
484	
485	  esp32p4_sdmmc_wait_idle();
486	
487	  /* 等待上一个命令被 CIU 接受 */
488	  timeout = 10000;
489	  while (!sdmmc_ll_is_command_taken(hw))
490	    {
491	      if (--timeout == 0)
492	        {
493	          mcerr("CMD%lu pre-wait timeout\n", (unsigned long)cmdidx);
494	          return -ETIMEDOUT;
495	        }
496	      up_udelay(1);
497	    }
498	
499	  /* 清除中断 */
500	  sdmmc_ll_clear_interrupt(hw, SDMMC_LL_EVENT_DEFAULT);
501	
502	  /* 写命令参数 */
503	  sdmmc_ll_set_command_arg(hw, arg);
504	
505	  /* 构建命令结构体 */
506	  memset(&s_cmd, 0, sizeof(s_cmd));
507	  s_cmd.cmd_index = cmdidx;
508	  s_cmd.wait_complete = 1;
509	  s_cmd.use_hold_reg = 1;
510	  s_cmd.card_num = state->slot;
511	
512	  if (cmdidx == 0)
513	    {
514	      s_cmd.send_init = 1;
515	    }
516	
517	  if ((cmd & MMCSD_RESPONSE_MASK) != MMCSD_NO_RESPONSE)
518	    {
519	      s_cmd.response_expect = 1;
520	      s_cmd.check_response_crc = 1;
521	
522	      if ((cmd & MMCSD_RESPONSE_MASK) == MMCSD_R2_RESPONSE)
523	        {
524	          s_cmd.response_long = 1;
525	        }
526	    }
527	
528	  if (cmd & MMCSD_R1B_RESPONSE)
529	    {
530	      s_cmd.stop_abort_cmd = 1;
531	    }
532	
533	  if (cmd & MMCSD_DATAXFR)
534	    {
535	      s_cmd.data_expected = 1;
536	
537	      if (cmd & MMCSD_WRDATAXFR)
538	        {
539	          s_cmd.rw = 1;
540	        }
541	    }
542	
543	  s_cmd.start_command = 1;
544	
545	  sdmmc_ll_set_command(hw, s_cmd);
546	
547	  mcinfo("CMD%lu arg=0x%08lx\n", (unsigned long)cmdidx, (unsigned long)arg);
548	  return OK;
549	}
