551	static int esp32p4_sdmmc_recvshort(struct sdio_dev_s *dev, uint32_t cmd,
552	                                   uint32_t *R)
553	{
554	  sdmmc_dev_t *hw = SDMMC_LL_GET_HW(0);
555	  uint32_t cmdidx = cmd & MMCSD_CMDIDX_MASK;
556	  uint32_t timeout = 100000;
557	  uint32_t status;
558	
559	  while (timeout--)
560	    {
561	      status = sdmmc_ll_get_interrupt_raw(hw);
562	
563	      if (status & (SDMMC_LL_EVENT_RTO | SDMMC_LL_EVENT_RESP_ERR |
564	                    SDMMC_LL_EVENT_RCRC | SDMMC_LL_EVENT_HLE |
565	                    SDMMC_LL_EVENT_SBE | SDMMC_LL_EVENT_EBE))
566	        {
567	          mcerr("CMD%lu error status=0x%08lx\n",
568	                (unsigned long)cmdidx, (unsigned long)status);
569	          sdmmc_ll_clear_interrupt(hw, status);
570	          return -EIO;
571	        }
572	
573	      if (status & SDMMC_LL_EVENT_CMD_DONE)
574	        {
575	          break;
576	        }
577	      up_udelay(1);
578	    }
579	
580	  if ((status & SDMMC_LL_EVENT_CMD_DONE) == 0)
581	    {
582	      mcerr("CMD%lu timeout status=0x%08lx\n",
583	            (unsigned long)cmdidx, (unsigned long)sdmmc_ll_get_interrupt_raw(hw));
584	      return -ETIMEDOUT;
585	    }
586	
587	  sdmmc_ll_clear_interrupt(hw, SDMMC_LL_EVENT_CMD_DONE);
588	
589	  /* RESP0 直接存储短响应 */
590	  *R = hw->resp[0];
591	
592	  mcinfo("CMD%lu resp=0x%08lx\n", (unsigned long)cmdidx, (unsigned long)*R);
593	  return OK;
594	}
