629	    }
630	
631	  sdmmc_ll_clear_interrupt(hw, SDMMC_LL_EVENT_CMD_DONE);
632	
633	  /* Synopsys DW 控制器：R2 直接存储在 RESP0-RESP3 */
634	  R[0] = hw->resp[0];
635	  R[1] = hw->resp[1];
636	  R[2] = hw->resp[2];
637	  R[3] = hw->resp[3];
638	
639	  mcinfo("CMD%lu long resp: %08lx %08lx %08lx %08lx\n",
640	         (unsigned long)cmdidx,
641	         (unsigned long)R[3], (unsigned long)R[2],
642	         (unsigned long)R[1], (unsigned long)R[0]);
643	  return OK;
644	}
