646	/* ========================================================================
647	 * 数据接收（使用 LL 层 DMA）
648	 * ======================================================================== */
649	
650	static int esp32p4_sdmmc_recvsetup(struct sdio_dev_s *dev, uint8_t *buffer,
651	                                   size_t nbytes)
652	{
653	  struct esp32p4_sdmmc_state_s *state = esp32p4_sdmmc_get_state(dev);
654	  sdmmc_dev_t *hw = SDMMC_LL_GET_HW(0);
655	  uint32_t timeout;
656	  uint32_t status;
657	  uint32_t idsts;
658	
659	  DEBUGASSERT(((uintptr_t)buffer & 3) == 0);
660	  DEBUGASSERT((nbytes & 3) == 0);
661	
662	  esp32p4_sdmmc_wait_idle();
663	
664	  /* 复位 FIFO 和 DMA */
665	  sdmmc_ll_reset_fifo(hw);
666	  timeout = 10000;
667	  while (!sdmmc_ll_is_fifo_reset_done(hw))
668	    {
669	      if (--timeout == 0)
670	        {
671	          return -ETIMEDOUT;
672	        }
673	      up_udelay(10);
674	    }
675	
676	  sdmmc_ll_reset_dma(hw);
677	  timeout = 10000;
678	  while (!sdmmc_ll_is_dma_reset_done(hw))
679	    {
680	      if (--timeout == 0)
681	        {
682	          return -ETIMEDOUT;
683	        }
684	      up_udelay(10);
685	    }
686	
687	  sdmmc_ll_set_data_transfer_len(hw, nbytes);
688	  sdmmc_ll_set_block_size(hw, 512);
689	
690	  esp32p4_sdmmc_setup_dma(state, buffer, nbytes, false);
691	
692	  sdmmc_ll_enable_interrupt(hw,
693	                            SDMMC_LL_EVENT_DATA_OVER | SDMMC_LL_EVENT_DTO |
694	                            SDMMC_LL_EVENT_DCRC | SDMMC_LL_EVENT_CMD_DONE |
695	                            SDMMC_LL_EVENT_HTO | SDMMC_LL_EVENT_FRUN,
696	                            true);
697	
698	  sdmmc_ll_clear_interrupt(hw, 0xFFFFFFFF);
699	  sdmmc_ll_clear_idsts_interrupt(hw, 0xFFFFFFFF);
700	
701	  sdmmc_ll_enable_dma(hw, true);
702	
703	  /* 轮询等待 */
704	  timeout = 0xFFFFFF;
705	  bool data_done = false;
706	  bool dma_done = false;
707	
708	  while (timeout--)
709	    {
710	      status = sdmmc_ll_get_interrupt_raw(hw);
711	      idsts  = sdmmc_ll_get_idsts_interrupt_raw(hw);
712	
713	      if (status & (SDMMC_LL_EVENT_DCRC | SDMMC_LL_EVENT_FRUN |
714	                    SDMMC_LL_EVENT_HTO | SDMMC_LL_EVENT_EBE |
715	                    SDMMC_LL_EVENT_SBE | SDMMC_LL_EVENT_DTO))
716	        {
717	          mcerr("RX data error status=0x%08lx\n", (unsigned long)status);
718	          sdmmc_ll_clear_interrupt(hw, status);
719	          return -EIO;
720	        }
721	
722	      if (idsts & (SDMMC_LL_EVENT_DMA_MASK))
723	        {
724	          if (idsts & (1 << 2))  /* FBE */
725	            {
726	              mcerr("RX DMA error idsts=0x%08lx\n", (unsigned long)idsts);
727	              sdmmc_ll_clear_idsts_interrupt(hw, idsts);
728	              return -EIO;
729	            }
730	        }
731	
732	      if ((status & SDMMC_LL_EVENT_DATA_OVER) != 0)
733	        {
734	          data_done = true;
735	          sdmmc_ll_clear_interrupt(hw, SDMMC_LL_EVENT_DATA_OVER);
736	        }
737	
738	      if ((idsts & SDMMC_LL_EVENT_DMA_RI) != 0)
739	        {
740	          dma_done = true;
741	          sdmmc_ll_clear_idsts_interrupt(hw, SDMMC_LL_EVENT_DMA_RI);
742	        }
743	
744	      if (data_done && dma_done)
745	        {
746	          break;
747	        }
748	    }
749	
750	  if (!data_done || !dma_done)
751	    {
752	      mcerr("RX DMA timeout\n");
753	      return -ETIMEDOUT;
754	    }
755	
756	  SDMMC_INV_DCACHE((uintptr_t)buffer, (uintptr_t)buffer + nbytes);
757	
758	  return OK;
759	}
