943	/* ========================================================================
944	 * 初始化
945	 * ======================================================================== */
946	
947	int esp32p4_sdmmc_initialize(int slot, int minor)
948	{
949	  struct esp32p4_sdmmc_state_s *state = &g_sdmmc_state[slot];
950	  struct sdio_dev_s *dev;
951	  sdmmc_dev_t *hw = SDMMC_LL_GET_HW(0);
952	  int ret;
953	
954	  if (state->initialized)
955	    {
956	      return OK;
957	    }
958	
959	  memset(state, 0, sizeof(*state));
960	  state->slot = slot;
961	
962	  nxsem_init(&state->sem, 0, 0);
963	
964	  /* 1. LDO（Slot0 需要 1.8V/3.3V 电源） */
965	  if (slot == 0)
966	    {
967	      ret = esp32p4_sdmmc_ldo_init(state);
968	      if (ret < 0)
969	        {
970	          goto err_ldo;
971	        }
972	    }
973	
974	  /* 2. GPIO */
975	  ret = esp32p4_sdmmc_gpio_init(state);
976	  if (ret < 0)
977	    {
978	      goto err_gpio;
979	    }
980	
981	  /* 3. 使能 SDMMC 总线时钟（关键！必须在访问寄存器之前） */
982	  sdmmc_ll_enable_bus_clock(0, true);
983	
984	  /* 4. 复位 SDMMC 模块 */
985	  sdmmc_ll_reset_register(0);
986	
987	  /* 5. 选择时钟源并设置分频 */
988	  sdmmc_ll_select_clk_source(hw, SDMMC_CLK_SRC_PLL160M);
989	  sdmmc_ll_set_clock_div(hw, 400);  /* 160MHz / 400 = 400kHz */
990	  sdmmc_ll_init_phase_delay(hw);
991	
992	  /* 6. 控制器内部复位 */
993	  esp32p4_sdmmc_reset_controller();
994	
995	  /* 7. 超时配置 */
996	  sdmmc_ll_set_data_timeout(hw, 0xFFFFFF);
997	  sdmmc_ll_set_response_timeout(hw, 0xFF);
998	
999	  /* 8. 块大小 */
1000	  sdmmc_ll_set_block_size(hw, 512);
1001	
1002	  /* 9. 使能 Card Clock */
1003	  sdmmc_ll_enable_card_clock(hw, slot, true);
1004	
1005	  /* 10. 初始化 DMA */
1006	  sdmmc_ll_init_dma(hw);
1007	  sdmmc_ll_enable_dma(hw, true);
1008	
1009	  /* 11. 中断 */
1010	  state->cpuint = esp_setup_irq(ETS_SDIO_HOST_INTR_SOURCE,
1011	                                ESP_IRQ_PRIORITY_DEFAULT,
1012	                                ESP_IRQ_TRIGGER_LEVEL,
1013	                                esp32p4_sdmmc_interrupt,
1014	                                state);
1015	  if (state->cpuint < 0)
1016	    {
1017	      ret = state->cpuint;
1018	      goto err_irq;
1019	    }
1020	
1021	  sdmmc_ll_enable_interrupt(hw, SDMMC_LL_EVENT_DEFAULT, true);
1022	  sdmmc_ll_enable_global_interrupt(hw, true);
1023	
1024	  /* 12. 填充 sdio_dev_s */
1025	  dev = &state->dev;
1026	
1027	  nxmutex_init(&dev->mutex);
1028	
1029	#ifdef CONFIG_SDIO_MUXBUS
1030	  dev->lock             = esp32p4_sdmmc_lock;
1031	#endif
1032	  dev->reset            = esp32p4_sdmmc_reset;
1033	  dev->capabilities     = esp32p4_sdmmc_capabilities;
1034	  dev->status           = esp32p4_sdmmc_status;
1035	  dev->widebus          = esp32p4_sdmmc_widebus;
1036	  dev->clock            = esp32p4_sdmmc_clock;
1037	  dev->attach           = esp32p4_sdmmc_attach;
1038	  dev->sendcmd          = esp32p4_sdmmc_sendcmd;
1039	  dev->recvsetup        = esp32p4_sdmmc_recvsetup;
1040	  dev->sendsetup        = esp32p4_sdmmc_sendsetup;
1041	  dev->cancel           = esp32p4_sdmmc_cancel;
1042	  dev->waitresponse     = esp32p4_sdmmc_waitresponse;
1043	  dev->recv_r1          = esp32p4_sdmmc_recvshort;
1044	  dev->recv_r2          = esp32p4_sdmmc_recvlong;
1045	  dev->recv_r3          = esp32p4_sdmmc_recvshort;
1046	  dev->recv_r4          = esp32p4_sdmmc_recvshort;
1047	  dev->recv_r5          = esp32p4_sdmmc_recvshort;
1048	  dev->recv_r6          = esp32p4_sdmmc_recvshort;
1049	  dev->recv_r7          = esp32p4_sdmmc_recvshort;
1050	  dev->waitenable       = esp32p4_sdmmc_waitenable;
1051	  dev->eventwait        = esp32p4_sdmmc_eventwait;
1052	  dev->callbackenable   = esp32p4_sdmmc_callbackenable;
1053	#if defined(CONFIG_SCHED_WORKQUEUE) && defined(CONFIG_SCHED_HPWORK)
1054	  dev->registercallback = esp32p4_sdmmc_registercallback;
1055	#endif
1056	  dev->gotextcsd        = esp32p4_sdmmc_gotextcsd;
1057	
1058	  /* 13. 注册到 mmcsd 子系统 */
1059	  ret = mmcsd_slotinitialize(minor, dev);
1060	  if (ret < 0)
1061	    {
1062	      goto err_mmcsd;
1063	    }
1064	
1065	  state->initialized = true;
1066	  mcinfo("Slot %d -> /dev/mmcsd%d initialized\n", slot, minor);
1067	
1068	  return OK;
1069	
1070	err_mmcsd:
1071	  esp_teardown_irq(ETS_SDIO_HOST_INTR_SOURCE, state->cpuint);
1072	err_irq:
1073	err_gpio:
1074	  esp32p4_sdmmc_ldo_deinit(state);
1075	err_ldo:
1076	  nxsem_destroy(&state->sem);
1077	  return ret;
1078	}
