72	esp_err_t sd_host_create_sdmmc_controller(const sd_host_sdmmc_cfg_t *config, sd_host_ctlr_handle_t *ret_handle)
73	{
74	    esp_err_t ret = ESP_FAIL;
75	    ESP_RETURN_ON_FALSE(config && ret_handle, ESP_ERR_INVALID_ARG, TAG, "invalid argument: null pointer");
76	
77	    sd_host_sdmmc_ctlr_t *ctlr = heap_caps_calloc(1, sizeof(sd_host_sdmmc_ctlr_t), SD_HOST_SDMMC_MEM_ALLOC_CAPS);
78	    ESP_RETURN_ON_FALSE(ctlr, ESP_ERR_NO_MEM, TAG, "no mem for sd host controller context");
79	
80	    ret = sd_host_claim_controller(ctlr);
81	    if (ret != ESP_OK) {
82	        //claim fail, clean and return directly
83	        free(ctlr);
84	        ESP_RETURN_ON_ERROR(ret, TAG, "no available sd host controller");
85	    }
86	
87	    ctlr->dma_desc_num = config->dma_desc_num ? config->dma_desc_num : SD_HOST_SDMMC_DMA_DESC_CNT;
88	    ctlr->dma_desc = heap_caps_calloc(1, sizeof(sdmmc_desc_t) * ctlr->dma_desc_num, SD_HOST_SDMMC_DMA_ALLOC_CAPS);
89	    ESP_LOGD(TAG, "ctlr->dma_desc addr: %p", ctlr->dma_desc);
90	    ESP_RETURN_ON_FALSE(ctlr->dma_desc, ESP_ERR_NO_MEM, TAG, "no mem for dma descriptors");
91	
92	    ctlr->io_intr_sem = xSemaphoreCreateBinaryWithCaps(SD_HOST_SDMMC_MEM_ALLOC_CAPS);
93	    ESP_GOTO_ON_FALSE(ctlr->io_intr_sem, ESP_ERR_NO_MEM, err, TAG, "no mem for io interrupt semaphore");
94	
95	    ctlr->mutex = xSemaphoreCreateMutexWithCaps(SD_HOST_SDMMC_MEM_ALLOC_CAPS);
96	    ESP_GOTO_ON_FALSE(ctlr->mutex, ESP_ERR_NO_MEM, err, TAG, "no mem for mutex");
97	
98	    ctlr->event_queue = xQueueCreateWithCaps(config->event_queue_items ? config->event_queue_items : 4, sizeof(sd_host_sdmmc_event_t), SD_HOST_SDMMC_MEM_ALLOC_CAPS);
99	    ESP_GOTO_ON_FALSE(ctlr->event_queue, ESP_ERR_NO_MEM, err, TAG, "no mem for mutex");
100	
101	    //use `ETS_SDIO_HOST_INTR_SOURCE` for now, replace with `sdmmc_periph.c` then. IDF-12585
102	    ESP_GOTO_ON_ERROR(esp_intr_alloc(ETS_SDIO_HOST_INTR_SOURCE, 0, &sd_host_isr, ctlr, &ctlr->intr_handle), err, TAG, "failed to install interrupt service");
103	
104	#if CONFIG_PM_ENABLE
105	    ESP_GOTO_ON_ERROR(esp_pm_lock_create(ESP_PM_APB_FREQ_MAX, 0, "sdmmc", &ctlr->pm_lock), err, TAG, "failed to create pm lock");
106	#endif //CONFIG_PM_ENABLE
107	
108	    sdmmc_hal_init(&ctlr->hal);
109	    sd_host_set_clk_div(ctlr, SDMMC_CLK_SRC_DEFAULT, 2);
110	
111	    // Reset
112	    esp_err_t err = sd_host_reset(ctlr);
113	    if (err != ESP_OK) {
114	        ESP_LOGE(TAG, "%s: sd_host_reset returned 0x%x", __func__, err);
115	        return err;
116	    }
117	
118	    ESP_LOGD(TAG, "peripheral version %"PRIx32", hardware config %08"PRIx32, sdmmc_ll_get_version_id(ctlr->hal.dev), sdmmc_ll_get_hw_config_info(ctlr->hal.dev));
119	
120	    sdmmc_ll_clear_interrupt(ctlr->hal.dev, 0xffffffff);
121	    sdmmc_ll_enable_interrupt(ctlr->hal.dev, 0xffffffff, false);
122	    sdmmc_ll_enable_global_interrupt(ctlr->hal.dev, false);
123	    sdmmc_ll_enable_interrupt(ctlr->hal.dev, SDMMC_LL_EVENT_DEFAULT, true);
124	    sdmmc_ll_enable_global_interrupt(ctlr->hal.dev, true);
125	    sdmmc_ll_init_dma(ctlr->hal.dev);
126	
127	    ctlr->spinlock = (portMUX_TYPE)portMUX_INITIALIZER_UNLOCKED;
128	    ctlr->drv.del_ctlr = sd_host_del_sdmmc_controller;
129	    *ret_handle = &ctlr->drv;
130	
131	    return ESP_OK;
132	
133	err:
134	    sd_host_del_sdmmc_controller(&ctlr->drv);
135	
136	    return ret;
137	}
