139	esp_err_t sd_host_sdmmc_controller_add_slot(sd_host_ctlr_handle_t ctlr, const sd_host_slot_sdmmc_init_cfg_t *config, sd_host_slot_handle_t *ret_handle)
140	{
141	    esp_err_t ret = ESP_FAIL;
142	    sd_host_sdmmc_ctlr_t *ctlr_ctx = __containerof(ctlr, sd_host_sdmmc_ctlr_t, drv);
143	    ESP_RETURN_ON_FALSE(ctlr && config && ret_handle, ESP_ERR_INVALID_ARG, TAG, "invalid argument: null pointer");
144	    ESP_RETURN_ON_FALSE(config->slot_id >= 0 && config->slot_id < SOC_SDMMC_NUM_SLOTS, ESP_ERR_INVALID_ARG, TAG, "invalid slot id");
145	
146	    sd_host_sdmmc_slot_t *slot = heap_caps_calloc(1, sizeof(sd_host_sdmmc_slot_t), SD_HOST_SDMMC_MEM_ALLOC_CAPS);
147	    ESP_RETURN_ON_FALSE(slot, ESP_ERR_NO_MEM, TAG, "no mem for sd host slot context");
148	
149	    bool slot_available = false;
150	    portENTER_CRITICAL(&ctlr_ctx->spinlock);
151	    if (!ctlr_ctx->slot[config->slot_id]) {
152	        slot_available = true;
153	        ctlr_ctx->slot[config->slot_id] = slot;
154	    }
155	    portEXIT_CRITICAL(&ctlr_ctx->spinlock);
156	    ESP_GOTO_ON_FALSE(slot_available, ESP_ERR_INVALID_STATE, err, TAG, "slot is not available");
157	
158	    portENTER_CRITICAL(&ctlr_ctx->spinlock);
159	    slot->slot_id = config->slot_id;
160	    slot->sd_mode = config->sd_mode;
161	    slot->freq.freq_hz = 400 * 1000;
162	    slot->freq.freq_state = SD_HOST_SLOT_STATE_INIT;
163	    slot->ctlr = ctlr_ctx;
164	    ctlr_ctx->registered_slot_nums = ctlr_ctx->registered_slot_nums + 1;
165	
166	    slot->drv.configure = sd_host_slot_sdmmc_configure;
167	    slot->drv.do_transaction = sd_host_slot_sdmmc_do_transaction;
168	    slot->drv.register_cbs = sd_host_slot_sdmmc_register_event_callbacks;
169	    slot->drv.remove_slot = sd_host_controller_remove_sdmmc_slot;
170	    slot->drv.set_cclk_always_on = sd_host_slot_sdmmc_set_cclk_always_on;
171	    slot->drv.enable_io_int = sd_host_slot_sdmmc_io_int_enable;
172	    slot->drv.wait_io_int = sd_host_slot_sdmmc_io_int_wait;
173	    slot->drv.get_info = sd_host_slot_sdmmc_get_info;
174	    portEXIT_CRITICAL(&ctlr_ctx->spinlock);
175	
176	    ESP_GOTO_ON_ERROR(sdmmc_slot_io_config(slot, config), err, TAG, "failed to config slot io");
177	
178	    *ret_handle = &slot->drv;
179	
180	    return ESP_OK;
181	
182	err:
183	    free(slot);
184	
185	    return ret;
186	}
