191	static esp_err_t sd_host_slot_sdmmc_configure(sd_host_slot_handle_t slot, const sd_host_slot_cfg_t *config)
192	{
193	    ESP_RETURN_ON_FALSE(slot && config, ESP_ERR_INVALID_ARG, TAG, "invalid argument: null pointer");
194	#if SDMMC_LL_DELAY_PHASE_SUPPORTED
195	    ESP_RETURN_ON_FALSE(config->delayphase < (SOC_SDMMC_DELAY_PHASE_NUM + 1), ESP_ERR_INVALID_ARG, TAG, "invalid delay phase");
196	#else
197	    //DIG-217
198	    ESP_LOGW(TAG, "esp32 doesn't support input phase delay, fallback to 0 delay");
199	#endif
200	
201	#if SOC_SDMMC_UHS_I_SUPPORTED
202	    ESP_RETURN_ON_FALSE(config->delayline < (SOC_SDMMC_DELAY_PHASE_NUM + 1), ESP_ERR_INVALID_ARG, TAG, "invalid delay line");
203	#else
204	    ESP_LOGW(TAG, "input line delay not supported, fallback to 0 delay");
205	#endif
206	
207	#if CONFIG_IDF_TARGET_ESP32P4
208	    if (config->freq_hz == SDMMC_FREQ_SDR104 * 1000) {
209	        unsigned chip_version = efuse_hal_chip_revision();
210	        ESP_LOGD(TAG, "chip_version: %d", chip_version);
211	        if (!ESP_CHIP_REV_ABOVE(chip_version, 300)) {
212	            ESP_RETURN_ON_FALSE(false, ESP_ERR_NOT_SUPPORTED, TAG, "UHS-I SDR104 is not supported on ESP32P4 chips prior than v3.0");
213	        }
214	    }
215	#endif
216	
217	    sd_host_sdmmc_slot_t *slot_ctx = __containerof(slot, sd_host_sdmmc_slot_t, drv);
218	    portENTER_CRITICAL(&slot_ctx->ctlr->spinlock);
219	    if (config->freq_hz != 0) {
220	        slot_ctx->freq.freq_hz = config->freq_hz;
221	        slot_ctx->freq.freq_state = SD_HOST_SLOT_STATE_READY;
222	    }
223	    if (config->width != 0) {
224	        slot_ctx->width.width_state = SD_HOST_SLOT_STATE_READY;
225	    }
226	    if (config->sampling_mode != 0) {
227	        slot_ctx->sampling_mode.mode = config->sampling_mode;
228	        slot_ctx->sampling_mode.sampling_mode_state = SD_HOST_SLOT_STATE_READY;
229	    }
230	    if (config->delayphase != 0) {
231	#if SDMMC_LL_DELAY_PHASE_SUPPORTED
232	        slot_ctx->delay_phase.delayphase = config->delayphase;
233	#else
234	        slot_ctx->delay_phase.delayphase = SDMMC_DELAY_PHASE_0;
235	#endif
236	        slot_ctx->delay_phase.delay_phase_state = SD_HOST_SLOT_STATE_READY;
237	    }
238	    if (config->delayline != 0) {
239	#if SOC_SDMMC_UHS_I_SUPPORTED
240	        slot_ctx->delay_line.delayline = config->delayline;
241	#else
242	        slot_ctx->delay_line.delayline = SDMMC_DELAY_LINE_0;
243	#endif
244	        slot_ctx->delay_line.delay_line_state = SD_HOST_SLOT_STATE_READY;
245	    }
246	    portEXIT_CRITICAL(&slot_ctx->ctlr->spinlock);
247	
248	    return ESP_OK;
249	}
