301	static esp_err_t sd_host_controller_remove_sdmmc_slot(sd_host_slot_handle_t slot)
302	{
303	    ESP_RETURN_ON_FALSE(slot, ESP_ERR_INVALID_ARG, TAG, "invalid argument: null pointer");
304	    sd_host_sdmmc_slot_t *slot_ctx = __containerof(slot, sd_host_sdmmc_slot_t, drv);
305	    sd_host_sdmmc_ctlr_t *ctlr = slot_ctx->ctlr;
306	
307	    bool slot_registered = false;
308	    portENTER_CRITICAL(&ctlr->spinlock);
309	    if (ctlr->slot[slot_ctx->slot_id]) {
310	        slot_registered = true;
311	        ctlr->slot[slot_ctx->slot_id] = NULL;
312	        ctlr->registered_slot_nums -= 1;
313	    }
314	    portEXIT_CRITICAL(&ctlr->spinlock);
315	    ESP_RETURN_ON_FALSE(slot_registered, ESP_ERR_INVALID_STATE, TAG, "slot is not registered");
316	
317	    if (slot_ctx->io_config.clk_io != GPIO_NUM_NC) {
318	        gpio_output_disable(slot_ctx->io_config.clk_io);
319	    }
320	    if (slot_ctx->io_config.cmd_io != GPIO_NUM_NC) {
321	        gpio_output_disable(slot_ctx->io_config.cmd_io);
322	    }
323	    if (slot_ctx->io_config.cd_io != GPIO_NUM_NC) {
324	        gpio_output_disable(slot_ctx->io_config.cd_io);
325	    }
326	    if (slot_ctx->io_config.wp_io != GPIO_NUM_NC) {
327	        gpio_output_disable(slot_ctx->io_config.wp_io);
328	    }
329	    if (slot_ctx->io_config.width >= 1) {
330	        gpio_output_disable(slot_ctx->io_config.d0_io);
331	    }
332	    if (slot_ctx->io_config.width >= 4) {
333	        gpio_output_disable(slot_ctx->io_config.d1_io);
334	        gpio_output_disable(slot_ctx->io_config.d2_io);
335	        gpio_output_disable(slot_ctx->io_config.d3_io);
336	    }
337	    if (slot_ctx->io_config.width == 8) {
338	        gpio_output_disable(slot_ctx->io_config.d4_io);
339	        gpio_output_disable(slot_ctx->io_config.d5_io);
340	        gpio_output_disable(slot_ctx->io_config.d6_io);
341	        gpio_output_disable(slot_ctx->io_config.d7_io);
342	    }
343	
344	    free(slot);
345	
346	    return ESP_OK;
347	}
