349	static esp_err_t sd_host_del_sdmmc_controller(sd_host_ctlr_handle_t ctlr)
350	{
351	    sd_host_sdmmc_ctlr_t *ctlr_ctx = __containerof(ctlr, sd_host_sdmmc_ctlr_t, drv);
352	    ESP_RETURN_ON_FALSE(ctlr, ESP_ERR_INVALID_ARG, TAG, "invalid argument: null pointer");
353	    ESP_RETURN_ON_FALSE(ctlr_ctx->registered_slot_nums == 0, ESP_ERR_INVALID_STATE, TAG, "host controller with slot registered");
354	
355	    ESP_RETURN_ON_ERROR(sd_host_declaim_controller(ctlr_ctx), TAG, "controller isn't in use");
356	    ESP_RETURN_ON_ERROR(esp_intr_free(ctlr_ctx->intr_handle), TAG, "failed to delete interrupt service");
357	
358	    if (ctlr_ctx->event_queue) {
359	        vQueueDeleteWithCaps(ctlr_ctx->event_queue);
360	    }
361	    if (ctlr_ctx->mutex) {
362	        vSemaphoreDeleteWithCaps(ctlr_ctx->mutex);
363	    }
364	    if (ctlr_ctx->io_intr_sem) {
365	        vSemaphoreDeleteWithCaps(ctlr_ctx->io_intr_sem);
366	    }
367	#if CONFIG_PM_ENABLE
368	    if (ctlr_ctx->pm_lock) {
369	        esp_pm_lock_delete(ctlr_ctx->pm_lock);
370	    }
371	#endif
372	
373	    free(ctlr_ctx->dma_desc);
374	    ctlr_ctx->dma_desc = NULL;
375	    free(ctlr_ctx);
376	    ctlr_ctx = NULL;
377	
378	    return ESP_OK;
379	}
