389	
390	static esp_err_t sd_host_slot_sdmmc_io_int_wait(sd_host_slot_handle_t slot, TickType_t timeout_ticks)
391	{
392	    ESP_RETURN_ON_FALSE(slot, ESP_ERR_INVALID_ARG, TAG, "invalid argument: null pointer");
393	    esp_err_t ret = ESP_FAIL;
394	    sd_host_sdmmc_slot_t *slot_ctx = __containerof(slot, sd_host_sdmmc_slot_t, drv);
395	
396	    /* SDIO interrupts are negedge sensitive ones: the status bit is only set
397	     * when first interrupt triggered.
398	     *
399	     * If D1 GPIO is low when entering this function, we know that interrupt
400	     * (in SDIO sense) has occurred and we don't need to use SDMMC peripheral
401	     * interrupt.
402	     */
403	
404	    /* Disable SDIO interrupt */
405	    if (slot_ctx->slot_id == 0) {
406	        sdmmc_ll_enable_interrupt(slot_ctx->ctlr->hal.dev, SDMMC_INTMASK_IO_SLOT0, false);
407	        sdmmc_ll_clear_interrupt(slot_ctx->ctlr->hal.dev, SDMMC_INTMASK_IO_SLOT0);
408	    } else {
409	        sdmmc_ll_enable_interrupt(slot_ctx->ctlr->hal.dev, SDMMC_INTMASK_IO_SLOT1, false);
410	        sdmmc_ll_clear_interrupt(slot_ctx->ctlr->hal.dev, SDMMC_INTMASK_IO_SLOT1);
411	    }
412	
413	    if (gpio_get_level(slot_ctx->io_config.d1_io) == 0) {
414	        return ESP_OK;
415	    }
416	    /* Otherwise, need to wait for an interrupt. Since D1 was high,
417	     * SDMMC peripheral interrupt is guaranteed to trigger on negedge.
418	     */
419	    xSemaphoreTake(slot_ctx->ctlr->io_intr_sem, 0);
420	
421	    /* Re-enable SDIO interrupt */
422	    if (slot_ctx->slot_id == 0) {
423	        sdmmc_ll_enable_interrupt(slot_ctx->ctlr->hal.dev, SDMMC_INTMASK_IO_SLOT0, true);
424	    } else {
425	        sdmmc_ll_enable_interrupt(slot_ctx->ctlr->hal.dev, SDMMC_INTMASK_IO_SLOT1, true);
426	    }
427	
428	    if (xSemaphoreTake(slot_ctx->ctlr->io_intr_sem, timeout_ticks) == pdTRUE) {
429	        ret = ESP_OK;
430	    } else {
431	        ret = ESP_ERR_TIMEOUT;
432	    }
433	
434	    return ret;
435	}
