455	bool sd_host_check_buffer_alignment(sd_host_sdmmc_slot_t *slot, const void *buf, size_t size)
456	{
457	    //for future-proof
458	    (void)slot;
459	    if (!buf || !size) {
460	        return false;
461	    }
462	
463	    esp_err_t ret = ESP_FAIL;
464	    int cache_flags = 0;
465	    size_t cache_alignment_bytes = 0;
466	    if (esp_ptr_external_ram(buf)) {
467	        cache_flags |= MALLOC_CAP_SPIRAM;
468	    }
469	    ret = esp_cache_get_alignment(cache_flags, &cache_alignment_bytes);
470	    assert(ret == ESP_OK);
471	    (void)ret;
472	
473	    bool is_aligned = false;
474	    size_t alignment = 0;
475	
476	    if (cache_alignment_bytes != 0) {
477	        alignment = cache_alignment_bytes;
478	    } else {
479	        alignment = SDMMC_DMA_ALIGNMENT;
480	    }
481	
482	    is_aligned = ((intptr_t)buf % alignment == 0) && (size % alignment == 0);
483	
484	    return is_aligned;
485	}
