487	esp_err_t sd_host_slot_set_card_clk(sd_host_sdmmc_slot_t *slot)
488	{
489	    // Disable clock first
490	    sdmmc_ll_enable_card_clock(slot->ctlr->hal.dev, slot->slot_id, false);
491	    esp_err_t ret = sd_host_slot_clock_update_command(slot, false);
492	    ESP_RETURN_ON_ERROR(ret, TAG, "%s: sd_host_slot_clock_update_command returned 0x%x, failed to disable clk, ", __func__, ret);
493	
494	    int freq_khz = 0;
495	    if (slot->freq.freq_state == SD_HOST_SLOT_STATE_READY) {
496	        freq_khz = slot->freq.freq_hz / 1000;
497	    } else {
498	        freq_khz = 400;
499	    }
500	    ESP_LOGD(TAG, "freq: %d khz, state: %d", freq_khz, slot->freq.freq_state);
501	
502	    soc_periph_sdmmc_clk_src_t clk_src = 0;
503	    int host_div = 0;   /* clock divider of the host (SDMMC.clock) */
504	    int card_div = 0;   /* 1/2 of card clock divider (SDMMC.clkdiv) */
505	    sd_host_slot_get_clk_dividers(slot, freq_khz, &host_div, &card_div, &clk_src);
506	
507	    int real_freq_khz = sd_host_calc_freq(clk_src, host_div, card_div);
508	    slot->freq.real_freq_hz = real_freq_khz * 1000;
509	    ESP_LOGD(TAG, "slot_id=%d clk_src=%d host_div=%d card_div=%d freq=%dkHz (max %" PRIu32 "kHz)", slot->slot_id, clk_src, host_div, card_div, real_freq_khz, freq_khz);
510	
511	    // Program card clock settings, send them to the CIU
512	    sdmmc_ll_set_card_clock_div(slot->ctlr->hal.dev, slot->slot_id, card_div);
513	    sd_host_set_clk_div(slot->ctlr, clk_src, host_div);
514	    ret = sd_host_slot_clock_update_command(slot, false);
515	    if (ret != ESP_OK) {
516	        ESP_LOGE(TAG, "setting clk div failed");
517	        ESP_LOGE(TAG, "%s: sd_host_slot_clock_update_command returned 0x%x", __func__, ret);
518	        return ret;
519	    }
520	
521	    // Re-enable clocks
522	    sdmmc_ll_enable_card_clock(slot->ctlr->hal.dev, slot->slot_id, true);
523	    sdmmc_ll_enable_card_clock_low_power(slot->ctlr->hal.dev, slot->slot_id, true);
524	    ret = sd_host_slot_clock_update_command(slot, false);
525	    if (ret != ESP_OK) {
526	        ESP_LOGE(TAG, "re-enabling clk failed");
527	        ESP_LOGE(TAG, "%s: sd_host_slot_clock_update_command returned 0x%x", __func__, ret);
528	        return ret;
529	    }
530	
531	    const uint32_t data_timeout_ms = 100;
532	    uint32_t data_timeout_cycles = data_timeout_ms * freq_khz;
533	    sdmmc_ll_set_data_timeout(slot->ctlr->hal.dev, data_timeout_cycles);
534	    // always set response timeout to highest value, it's small enough anyway
535	    sdmmc_ll_set_response_timeout(slot->ctlr->hal.dev, 255);
536	
537	    return ESP_OK;
538	}
539	
540	esp_err_t sd_host_slot_get_real_freq(sd_host_sdmmc_slot_t *slot, int *real_freq_khz)
541	{
542	    ESP_RETURN_ON_FALSE(slot && real_freq_khz, ESP_ERR_INVALID_ARG, TAG, "invalid argument: null pointer");
543	
544	    int host_div = 0;
545	    int card_div = 0;
546	    host_div = sdmmc_ll_get_clock_div(slot->ctlr->hal.dev);
547	    card_div = sdmmc_ll_get_card_clock_div(slot->ctlr->hal.dev, slot->slot_id);
548	    *real_freq_khz = sd_host_calc_freq(slot->clk_src, host_div, card_div);
549	
550	    return ESP_OK;
