612	esp_err_t sd_host_set_delay_phase(sd_host_sdmmc_slot_t *slot)
613	{
614	#if SDMMC_LL_DELAY_PHASE_SUPPORTED
615	    ESP_RETURN_ON_FALSE(slot, ESP_ERR_INVALID_ARG, TAG, "invalid argument: null pointer");
616	
617	    sdmmc_delay_phase_t delay_phase = SDMMC_DELAY_PHASE_0;
618	    if (slot->delay_phase.delay_phase_state == SD_HOST_SLOT_STATE_READY) {
619	        delay_phase = slot->delay_phase.delayphase;
620	    }
621	
622	    uint32_t clk_src_freq_hz = 0;
623	    ESP_RETURN_ON_ERROR(esp_clk_tree_src_get_freq_hz(slot->clk_src, ESP_CLK_TREE_SRC_FREQ_PRECISION_CACHED, &clk_src_freq_hz),
624	                        TAG, "get source clock frequency failed");
625	
626	    //Now we're in high speed. Note ESP SDMMC Host HW only supports integer divider.
627	    int delay_phase_num = 0;
628	    sdmmc_ll_delay_phase_t phase = SDMMC_LL_DELAY_PHASE_0;
629	    sdmmc_ll_speed_mode_t speed_mode = (slot->freq.freq_hz / 1000) == SDMMC_FREQ_SDR104 ? SDMMC_LL_SPEED_MODE_HS : SDMMC_LL_SPEED_MODE_LS;
630	    switch (delay_phase) {
631	    case SDMMC_DELAY_PHASE_1:
632	        phase = SDMMC_LL_DELAY_PHASE_1;
633	        delay_phase_num = 1;
634	        break;
635	    case SDMMC_DELAY_PHASE_2:
636	        phase = SDMMC_LL_DELAY_PHASE_2;
637	        delay_phase_num = 2;
638	        break;
639	    case SDMMC_DELAY_PHASE_3:
640	        phase = SDMMC_LL_DELAY_PHASE_3;
641	        delay_phase_num = 3;
642	        break;
643	#if SOC_SDMMC_DELAY_PHASE_NUM > 4
644	    case SDMMC_DELAY_PHASE_4:
645	        phase = SDMMC_LL_DELAY_PHASE_4;
646	        delay_phase_num = 4;
647	        break;
648	    case SDMMC_DELAY_PHASE_5:
649	        phase = SDMMC_LL_DELAY_PHASE_5;
650	        delay_phase_num = 5;
651	        break;
652	    case SDMMC_DELAY_PHASE_6:
653	        phase = SDMMC_LL_DELAY_PHASE_6;
654	        delay_phase_num = 6;
655	        break;
656	    case SDMMC_DELAY_PHASE_7:
657	        phase = SDMMC_LL_DELAY_PHASE_7;
658	        delay_phase_num = 7;
659	        break;
660	#endif
661	    default:
662	        phase = SDMMC_LL_DELAY_PHASE_0;
663	        delay_phase_num = 0;
664	        break;
665	    }
666	    PERIPH_RCC_ATOMIC() {
667	        sdmmc_ll_set_din_delay_phase(slot->ctlr->hal.dev, phase, speed_mode);
668	        sdmmc_ll_set_dout_delay_phase(slot->ctlr->hal.dev, phase, speed_mode);
669	    }
670	
671	    int src_clk_period_ps = (1 * 1000 * 1000) / (clk_src_freq_hz / (1 * 1000 * 1000));
672	    int delay_phase_total_num = (slot->freq.freq_hz / 1000) == SDMMC_FREQ_SDR104 ? SOC_SDMMC_DELAY_PHASE_NUM : SDMMC_LL_DELAY_MAX_NUMS_LS;
673	    ESP_LOGD(TAG, "slot->freq.freq_hz: %d, delay_phase_total_num: %d", slot->freq.freq_hz, delay_phase_total_num);
674	    int phase_diff_ps = src_clk_period_ps * sdmmc_ll_get_clock_div(slot->ctlr->hal.dev) / delay_phase_total_num;
675	    ESP_LOGD(TAG, "difference between delay phases is %d ps", phase_diff_ps);
676	    ESP_LOGD(TAG, "host sampling edge is delayed by %d ps", phase_diff_ps * delay_phase_num);
677	
678	    return ESP_OK;
679	#else
680	    //DIG-217
681	    ESP_LOGD(TAG, "esp32 doesn't support phase delay, fallback to 0 delay");
682	    return ESP_OK;
683	#endif
684	}
