745	static esp_err_t sd_host_claim_controller(sd_host_sdmmc_ctlr_t *controller)
746	{
747	    assert(controller);
748	
749	    _lock_acquire(&s_platform.mutex);
750	    bool found = false;
751	    for (int i = 0; i < SDMMC_LL_HOST_CTLR_NUMS; i ++) {
752	        found = !s_platform.controllers[i];
753	        if (found) {
754	            s_platform.controllers[i] = controller;
755	            controller->host_id = i;
756	            PERIPH_RCC_ATOMIC() {
757	                sdmmc_ll_enable_bus_clock(i, true);
758	                sdmmc_ll_reset_register(i);
759	            }
760	            break;
761	        }
762	    }
763	    _lock_release(&s_platform.mutex);
764	
765	    if (!found) {
766	        return ESP_ERR_NOT_FOUND;
767	    }
768	    return ESP_OK;
769	}
