776	    s_platform.controllers[controller->host_id] = NULL;
777	    PERIPH_RCC_ATOMIC() {
778	        sdmmc_ll_enable_bus_clock(0, false);
779	    }
780	    _lock_release(&s_platform.mutex);
781	
782	    return ESP_OK;
