785	/*---------------------------------------------------------------
786	                    Static: ISR Handler
787	---------------------------------------------------------------*/
788	static void sd_host_isr(void *arg)
789	{
790	    sd_host_sdmmc_ctlr_t *ctlr = (sd_host_sdmmc_ctlr_t *)arg;
791	    sd_host_sdmmc_slot_t *slot = ctlr->slot[ctlr->cur_slot_id];
792	
793	    sd_host_sdmmc_event_t event = {};
794	    bool need_yield = false;
795	    int higher_priority_task_awoken = pdFALSE;
796	
797	    uint32_t pending = sdmmc_ll_get_intr_status(ctlr->hal.dev) & SDMMC_LL_SD_EVENT_MASK;
798	    sdmmc_ll_clear_interrupt(ctlr->hal.dev, pending);
799	    event.sdmmc_status = pending;
800	
801	    uint32_t dma_pending = sdmmc_ll_get_idsts_interrupt_raw(ctlr->hal.dev);
802	    sdmmc_ll_clear_idsts_interrupt(ctlr->hal.dev, dma_pending);
803	
804	    if (dma_pending & SDMMC_LL_EVENT_DMA_NI) {
805	        // refill DMA descriptors
806	        size_t free_desc = sd_host_get_free_descriptors_count(slot);
807	        if (free_desc > 0) {
808	            sd_host_fill_dma_descriptors(slot, free_desc);
809	            sd_host_dma_resume(slot);
810	        }
811	        //NI, logic OR of TI and RI. This is a sticky bit and must be cleared each time TI or RI is cleared.
812	        dma_pending &= ~(SDMMC_LL_EVENT_DMA_NI | SDMMC_LL_EVENT_DMA_TI | SDMMC_LL_EVENT_DMA_RI);
813	    }
814	    event.dma_status = dma_pending & SDMMC_LL_EVENT_DMA_MASK;
815	
816	    if (pending != 0 || dma_pending != 0) {
817	        xQueueSendFromISR(ctlr->event_queue, &event, &higher_priority_task_awoken);
818	        if (slot->cbs.on_trans_done) {
819	            sd_host_evt_data_t edata = {};
820	            if (slot->cbs.on_trans_done(&slot->drv, &edata, slot->user_data)) {
821	                need_yield |= true;
822	            }
823	        }
824	    }
825	
826	    uint32_t sdio_pending = (sdmmc_ll_get_intr_status(ctlr->hal.dev) & (SDMMC_INTMASK_IO_SLOT1 | SDMMC_INTMASK_IO_SLOT0));
827	    if (sdio_pending) {
828	        // disable the interrupt (no need to clear here, this is done in sdmmc_host_io_int_wait)
829	        sdmmc_ll_enable_interrupt(ctlr->hal.dev, sdio_pending, false);
830	        xSemaphoreGiveFromISR(ctlr->io_intr_sem, &higher_priority_task_awoken);
831	        if (slot->cbs.on_io_interrupt) {
832	            sd_host_evt_data_t edata = {};
833	            if (slot->cbs.on_io_interrupt(&slot->drv, &edata, slot->user_data)) {
834	                need_yield |= true;
835	            }
836	        }
837	    }
838	
839	    need_yield |= higher_priority_task_awoken == pdTRUE;
840	    if (need_yield) {
841	        portYIELD_FROM_ISR();
842	    }
843	}
