845	/*---------------------------------------------------------------
846	                    HW Commands
847	---------------------------------------------------------------*/
848	esp_err_t sd_host_slot_start_command(sd_host_sdmmc_slot_t *slot, sdmmc_hw_cmd_t cmd, uint32_t arg)
849	{
850	    ESP_RETURN_ON_FALSE(slot, ESP_ERR_INVALID_ARG, TAG, "invalid argument: null pointer");
851	
852	    // if this isn't a clock update command, check the card detect status
853	    if (!sdmmc_ll_is_card_detected(slot->ctlr->hal.dev, slot->slot_id) && !cmd.update_clk_reg) {
854	        return ESP_ERR_NOT_FOUND;
855	    }
856	    if (cmd.data_expected && cmd.rw && sdmmc_ll_is_card_write_protected(slot->ctlr->hal.dev, slot->slot_id)) {
857	        return ESP_ERR_INVALID_STATE;
858	    }
859	    /* Outputs should be synchronized to cclk_out */
860	    cmd.use_hold_reg = 1;
861	
862	    int64_t yield_delay_us = 100 * 1000; // initially 100ms
863	    int64_t t0 = esp_timer_get_time();
864	    int64_t t1 = 0;
865	    bool skip_wait = (cmd.volt_switch && cmd.update_clk_reg);
866	    if (!skip_wait) {
867	        while (!(sdmmc_ll_is_command_taken(slot->ctlr->hal.dev))) {
868	            t1 = esp_timer_get_time();
869	            if (t1 - t0 > SD_HOST_SDMMC_START_CMD_TIMEOUT_US) {
870	                return ESP_ERR_TIMEOUT;
871	            }
872	            if (t1 - t0 > yield_delay_us) {
873	                yield_delay_us *= 2;
874	                vTaskDelay(1);
875	            }
876	        }
877	    }
878	    sdmmc_ll_set_command_arg(slot->ctlr->hal.dev, arg);
879	    cmd.card_num = slot->slot_id;
880	    cmd.start_command = 1;
881	    sdmmc_ll_set_command(slot->ctlr->hal.dev, cmd);
882	
883	    while (!(sdmmc_ll_is_command_taken(slot->ctlr->hal.dev))) {
884	        t1 = esp_timer_get_time();
885	        if (t1 - t0 > SD_HOST_SDMMC_START_CMD_TIMEOUT_US) {
886	            return ESP_ERR_TIMEOUT;
887	        }
888	        if (t1 - t0 > yield_delay_us) {
889	            yield_delay_us *= 2;
890	            vTaskDelay(1);
891	        }
892	    }
893	    return ESP_OK;
894	}
