953	/*---------------------------------------------------------------
954	                    Static: Clock
955	---------------------------------------------------------------*/
956	/* We have two clock divider stages:
957	 * - one is the clock generator which drives SDMMC peripheral,
958	 *   it can be configured using SDMMC.clock register. It can generate
959	 *   frequencies 160MHz/(N + 1), where 0 < N < 16, I.e. from 10 to 80 MHz.
960	 * - 4 clock dividers inside SDMMC peripheral, which can divide clock
961	 *   from the first stage by 2 * M, where 0 < M < 255
962	 *   (they can also be bypassed).
963	 *
964	 * For cards which aren't UHS-1 or UHS-2 cards, which we don't support,
965	 * maximum bus frequency in high speed (HS) mode is 50 MHz.
966	 * Note: for non-UHS-1 cards, HS mode is optional.
967	 * Default speed (DS) mode is mandatory, it works up to 25 MHz.
968	 * Whether the card supports HS or not can be determined using TRAN_SPEED
969	 * field of card's CSD register.
970	 *
971	 * 50 MHz can not be obtained exactly, closest we can get is 53 MHz.
972	 *
973	 * The first stage divider is set to the highest possible value for the given
974	 * frequency, and the the second stage dividers are used if division factor
975	 * is >16.
976	 *
977	 * Of the second stage dividers, div0 is used for card 0, and div1 is used
978	 * for card 1.
979	 */
980	static void sd_host_set_clk_div(sd_host_sdmmc_ctlr_t *ctlr, soc_periph_sdmmc_clk_src_t src, int div)
981	{
982	    ESP_ERROR_CHECK(esp_clk_tree_enable_src((soc_module_clk_t)src, true));
983	    PERIPH_RCC_ATOMIC() {
984	        sdmmc_ll_set_clock_div(ctlr->hal.dev, div);
985	        sdmmc_ll_select_clk_source(ctlr->hal.dev, src);
986	        sdmmc_ll_init_phase_delay(ctlr->hal.dev);
987	#if SDMMC_LL_SDIO_PLL_SUPPORTED
988	        if (src == SDMMC_CLK_SRC_SDIO_200M) {
989	            sdmmc_ll_enable_sdio_pll(ctlr->hal.dev, true);
990	        }
991	#endif
992	    }
993	
994	    // Wait for the clock to propagate
995	    esp_rom_delay_us(10);
996	}
997	
998	static void sd_host_slot_get_clk_dividers(sd_host_sdmmc_slot_t *slot, uint32_t freq_khz, int *host_div, int *card_div, soc_periph_sdmmc_clk_src_t *src)
999	{
1000	    uint32_t clk_src_freq_hz = 0;
1001	    soc_periph_sdmmc_clk_src_t clk_src = 0;
1002	#if SOC_SDMMC_UHS_I_SUPPORTED
1003	    if (freq_khz > SDMMC_FREQ_HIGHSPEED) {
1004	        clk_src = SDMMC_CLK_SRC_SDIO_200M;
1005	    } else
1006	#endif
1007	    {
1008	        clk_src = SDMMC_CLK_SRC_DEFAULT;
1009	    }
1010	    slot->clk_src = clk_src;
1011	
1012	    esp_err_t ret = esp_clk_tree_src_get_freq_hz(clk_src, ESP_CLK_TREE_SRC_FREQ_PRECISION_CACHED, &clk_src_freq_hz);
1013	    assert(ret == ESP_OK);
1014	    (void)ret;
1015	    ESP_LOGD(TAG, "clk_src_freq_hz: %"PRId32" hz", clk_src_freq_hz);
1016	
1017	#if SDMMC_LL_MAX_FREQ_KHZ_FPGA
1018	    if (freq_khz >= SDMMC_LL_MAX_FREQ_KHZ_FPGA) {
1019	        ESP_LOGW(TAG, "working on FPGA, fallback to use the %d KHz", SDMMC_LL_MAX_FREQ_KHZ_FPGA);
1020	        freq_khz = SDMMC_LL_MAX_FREQ_KHZ_FPGA;
1021	    }
1022	#endif
1023	
1024	    // Calculate new dividers
1025	#if SOC_SDMMC_UHS_I_SUPPORTED
1026	    if (freq_khz == SDMMC_FREQ_SDR104) {
1027	        *host_div = 1;       // 200 MHz / 1 = 200 MHz
1028	        *card_div = 0;
1029	    } else if (freq_khz == SDMMC_FREQ_SDR50) {
1030	        *host_div = 2;       // 200 MHz / 2 = 100 MHz
1031	        *card_div = 0;
1032	    } else
1033	#endif
1034	        if (freq_khz >= SDMMC_FREQ_HIGHSPEED) {
1035	            *host_div = 4;       // 160 MHz / 4 = 40 MHz
1036	            *card_div = 0;
1037	        } else if (freq_khz == SDMMC_FREQ_DEFAULT) {
1038	            *host_div = 8;       // 160 MHz / 8 = 20 MHz
1039	            *card_div = 0;
1040	        } else if (freq_khz == SDMMC_FREQ_PROBING) {
1041	            *host_div = 10;      // 160 MHz / 10 / (20 * 2) = 400 kHz
1042	            *card_div = 20;
1043	        } else {
1044	            /*
1045	             * for custom frequencies use maximum range of host divider (1-16), find the closest <= div. combination
1046	             * if exceeded, combine with the card divider to keep reasonable precision (applies mainly to low frequencies)
1047	             * effective frequency range: 400 kHz - 32 MHz (32.1 - 39.9 MHz cannot be covered with given divider scheme)
1048	             */
1049	            *host_div = (clk_src_freq_hz) / (freq_khz * 1000);
1050	            if (*host_div > 15) {
1051	                *host_div = 2;
1052	                *card_div = (clk_src_freq_hz / 2) / (2 * freq_khz * 1000);
1053	                if (((clk_src_freq_hz / 2) % (2 * freq_khz * 1000)) > 0) {
1054	                    (*card_div)++;
1055	                }
1056	            } else if ((clk_src_freq_hz % (freq_khz * 1000)) > 0) {
1057	                (*host_div)++;
1058	            }
1059	        }
1060	
1061	    *src = clk_src;
1062	}
1063	
1064	static int sd_host_calc_freq(soc_periph_sdmmc_clk_src_t src, const int host_div, const int card_div)
1065	{
1066	    uint32_t clk_src_freq_hz = 0;
1067	    esp_err_t ret = esp_clk_tree_src_get_freq_hz(src, ESP_CLK_TREE_SRC_FREQ_PRECISION_CACHED, &clk_src_freq_hz);
1068	    assert(ret == ESP_OK);
1069	    (void)ret;
1070	
1071	    return clk_src_freq_hz / host_div / ((card_div == 0) ? 1 : card_div * 2) / 1000;
1072	}
