1077	static void configure_pin_iomux(uint8_t gpio_num)
1078	{
1079	    assert(gpio_num != (uint8_t) GPIO_NUM_NC);
1080	    gpio_pulldown_dis(gpio_num);
1081	    gpio_input_enable(gpio_num);
1082	    gpio_iomux_output(gpio_num, SDMMC_LL_IOMUX_FUNC);
1083	#if !CONFIG_IDF_TARGET_ESP32
1084	    /**
1085	     * On ESP32, the default pin drive value (2) works
1086	     */
1087	    gpio_set_drive_capability(gpio_num, 3);
1088	#endif
1089	}
