1091	static void configure_pin_gpio_matrix(uint8_t gpio_num, uint8_t gpio_matrix_sig, gpio_mode_t mode, const char *name)
1092	{
1093	    assert(gpio_num != (uint8_t) GPIO_NUM_NC);
1094	    ESP_LOGD(TAG, "using GPIO%d as %s pin", gpio_num, name);
1095	    //todo: IDF-11125
1096	    gpio_reset_pin(gpio_num);
1097	    gpio_set_direction(gpio_num, mode);
1098	    gpio_pulldown_dis(gpio_num);
1099	    if (mode == GPIO_MODE_INPUT || mode == GPIO_MODE_INPUT_OUTPUT) {
1100	        esp_rom_gpio_connect_in_signal(gpio_num, gpio_matrix_sig, false);
1101	    }
1102	    if (mode == GPIO_MODE_OUTPUT || mode == GPIO_MODE_INPUT_OUTPUT) {
1103	        esp_rom_gpio_connect_out_signal(gpio_num, gpio_matrix_sig, false, false);
1104	    }
1105	}
