1107	static void configure_pin(uint8_t gpio_num, uint8_t gpio_matrix_sig, gpio_mode_t mode, const char *name, bool use_gpio_matrix)
1108	{
1109	    if (use_gpio_matrix) {
1110	        configure_pin_gpio_matrix(gpio_num, gpio_matrix_sig, mode, name);
1111	    } else {
1112	        configure_pin_iomux(gpio_num);
1113	    }
1114	}
