1116	//True: pins are all not set; False: one or more pins are set
1117	static bool s_check_pin_not_set(const sd_host_sdmmc_slot_io_cfg_t *io_config)
1118	{
1119	#if SOC_SDMMC_USE_GPIO_MATRIX
1120	    bool pin_not_set = !io_config->clk_io && !io_config->cmd_io && !io_config->d0_io && !io_config->d1_io && !io_config->d2_io &&
1121	                       !io_config->d3_io && !io_config->d4_io && !io_config->d5_io && !io_config->d6_io && !io_config->d7_io;
1122	    return pin_not_set;
1123	#else
1124	    return true;
1125	#endif
