1128	static esp_err_t sdmmc_host_pullup_en_internal(sd_host_sdmmc_slot_t *slot)
1129	{
1130	    if (slot->width.width > sdmmc_slot_info[slot->slot_id].width) {
1131	        //in esp32 we only support 8 bit in slot 0, note this is occupied by the flash by default
1132	        return ESP_ERR_INVALID_ARG;
1133	    }
1134	    // according to the spec, the host controls the clk, we don't to pull it up here
1135	    gpio_pullup_en(slot->io_config.cmd_io);
1136	    gpio_pullup_en(slot->io_config.d0_io);
1137	    if (slot->width.width >= 4) {
1138	        gpio_pullup_en(slot->io_config.d1_io);
1139	        gpio_pullup_en(slot->io_config.d2_io);
1140	        gpio_pullup_en(slot->io_config.d3_io);
1141	    }
1142	    if (slot->width.width == 8) {
1143	        gpio_pullup_en(slot->io_config.d4_io);
1144	        gpio_pullup_en(slot->io_config.d5_io);
1145	        gpio_pullup_en(slot->io_config.d6_io);
1146	        gpio_pullup_en(slot->io_config.d7_io);
1147	    }
1148	    return ESP_OK;
1149	}
