1151	static esp_err_t sdmmc_slot_io_config(sd_host_sdmmc_slot_t *slot, const sd_host_slot_sdmmc_init_cfg_t *slot_init_config)
1152	{
1153	    bool gpio_wp_polarity = slot_init_config->slot_flags.wp_active_high;
1154	    sd_bus_width_t slot_width = slot_init_config->io_config.width;
1155	    int slot_id = slot_init_config->slot_id;
1156	
1157	    const sdmmc_slot_info_t *slot_info = &sdmmc_slot_info[slot_id];
1158	    ESP_RETURN_ON_FALSE(slot_width <= slot_info->width, ESP_ERR_INVALID_ARG, TAG, "wrong slot width");
1159	    if (slot_width == SD_HOST_SLOT_WIDTH_DEFAULT) {
1160	        slot_width = slot_info->width;
1161	    }
1162	
1163	    const sd_host_sdmmc_slot_io_cfg_t *io_config = &slot_init_config->io_config;
1164	    sd_host_sdmmc_slot_io_cfg_t *slot_gpio = &slot->io_config;
1165	
1166	    slot->io_config.clk_io = GPIO_NUM_NC;
1167	    slot->io_config.cmd_io = GPIO_NUM_NC;
1168	    slot->io_config.cd_io = GPIO_NUM_NC;
1169	    slot->io_config.wp_io = GPIO_NUM_NC;
1170	    slot->io_config.d0_io = GPIO_NUM_NC;
1171	    slot->io_config.d1_io = GPIO_NUM_NC;
1172	    slot->io_config.d2_io = GPIO_NUM_NC;
1173	    slot->io_config.d3_io = GPIO_NUM_NC;
1174	    slot->io_config.d4_io = GPIO_NUM_NC;
1175	    slot->io_config.d5_io = GPIO_NUM_NC;
1176	    slot->io_config.d6_io = GPIO_NUM_NC;
1177	    slot->io_config.d7_io = GPIO_NUM_NC;
1178	    slot->width.width = slot_width;
1179	    slot->width.width_state = SD_HOST_SLOT_STATE_INIT;
1180	    slot_gpio->cd_io = io_config->cd_io;
1181	    slot_gpio->wp_io = io_config->wp_io;
1182	
1183	    bool pin_not_set = s_check_pin_not_set(io_config);
1184	    //SD driver behaviour is: all pins not defined == using iomux
1185	    bool use_gpio_matrix = !pin_not_set;
1186	
1187	    if (slot_id == 0) {
1188	#if !SDMMC_LL_SLOT_SUPPORT_GPIO_MATRIX(0)
1189	        if (use_gpio_matrix) {
1190	            if (slot_width >= 1) {
1191	                if (SDMMC_SLOT0_IOMUX_PIN_NUM_CLK == io_config->clk_io && SDMMC_SLOT0_IOMUX_PIN_NUM_CMD == io_config->cmd_io && SDMMC_SLOT0_IOMUX_PIN_NUM_D0 == io_config->d0_io) {
1192	                    use_gpio_matrix = false;
1193	                } else {
1194	                    use_gpio_matrix = true;
1195	                }
1196	            }
1197	            if (slot_width >= 4) {
1198	                if (SDMMC_SLOT0_IOMUX_PIN_NUM_D1 == io_config->d1_io && SDMMC_SLOT0_IOMUX_PIN_NUM_D2 == io_config->d2_io && SDMMC_SLOT0_IOMUX_PIN_NUM_D3 == io_config->d3_io) {
1199	                    use_gpio_matrix = false;
1200	                } else {
1201	                    use_gpio_matrix = true;
1202	                }
1203	            }
1204	        } else {
1205	            ESP_RETURN_ON_FALSE(!use_gpio_matrix, ESP_ERR_INVALID_ARG, TAG, "doesn't support routing from GPIO matrix, driver uses dedicated IOs");
1206	        }
1207	#endif
1208	    } else {
1209	#if !SDMMC_LL_SLOT_SUPPORT_GPIO_MATRIX(1)
1210	        ESP_RETURN_ON_FALSE(!use_gpio_matrix, ESP_ERR_INVALID_ARG, TAG, "doesn't support routing from GPIO matrix, driver uses dedicated IOs");
1211	#endif
1212	    }
1213	    slot->use_gpio_matrix = use_gpio_matrix;
1214	
1215	#if SOC_SDMMC_USE_GPIO_MATRIX
1216	    if (use_gpio_matrix) {
1217	        /* Save pin configuration for this slot */
1218	        slot_gpio->clk_io = io_config->clk_io;
1219	        slot_gpio->cmd_io = io_config->cmd_io;
1220	        slot_gpio->d0_io = io_config->d0_io;
1221	        /* Save d1 even in 1-line mode, it might be needed for SDIO INT line */
1222	        slot_gpio->d1_io = io_config->d1_io;
1223	        if (slot_width >= 4) {
1224	            slot_gpio->d2_io = io_config->d2_io;
1225	        }
1226	        /* Save d3 even for 1-line mode, as it needs to be set high */
1227	        slot_gpio->d3_io = io_config->d3_io;
1228	        if (slot_width >= 8) {
1229	            slot_gpio->d4_io = io_config->d4_io;
1230	            slot_gpio->d5_io = io_config->d5_io;
1231	            slot_gpio->d6_io = io_config->d6_io;
1232	            slot_gpio->d7_io = io_config->d7_io;
1233	        }
1234	    } else
1235	#endif  //#if SOC_SDMMC_USE_GPIO_MATRIX
1236	    {
1237	        /* init pin configuration for this slot */
1238	        slot_gpio->clk_io = sdmmc_slot_gpio_num[slot_id].clk;
1239	        slot_gpio->cmd_io = sdmmc_slot_gpio_num[slot_id].cmd;
1240	        slot_gpio->d0_io = sdmmc_slot_gpio_num[slot_id].d0;
1241	        slot_gpio->d1_io = sdmmc_slot_gpio_num[slot_id].d1;
1242	        slot_gpio->d2_io = sdmmc_slot_gpio_num[slot_id].d2;
1243	        slot_gpio->d3_io = sdmmc_slot_gpio_num[slot_id].d3;
1244	        slot_gpio->d4_io = sdmmc_slot_gpio_num[slot_id].d4;
1245	        slot_gpio->d5_io = sdmmc_slot_gpio_num[slot_id].d5;
1246	        slot_gpio->d6_io = sdmmc_slot_gpio_num[slot_id].d6;
1247	        slot_gpio->d7_io = sdmmc_slot_gpio_num[slot_id].d7;
1248	    }
1249	
1250	    bool pullup = slot_init_config->slot_flags.internal_pullup;
1251	    if (pullup) {
1252	        sdmmc_host_pullup_en_internal(slot);
1253	    }
1254	
1255	    if (slot_width >= 1) {
1256	        GPIO_NUM_CHECK(slot_gpio->clk_io);
1257	        GPIO_NUM_CHECK(slot_gpio->cmd_io);
1258	        GPIO_NUM_CHECK(slot_gpio->d0_io);
1259	    }
1260	    if (slot_width >= 4) {
1261	        GPIO_NUM_CHECK(slot_gpio->d1_io);
1262	        GPIO_NUM_CHECK(slot_gpio->d2_io);
1263	        GPIO_NUM_CHECK(slot_gpio->d3_io);
1264	    }
1265	    if (slot_width == 8) {
1266	        GPIO_NUM_CHECK(slot_gpio->d4_io);
1267	        GPIO_NUM_CHECK(slot_gpio->d5_io);
1268	        GPIO_NUM_CHECK(slot_gpio->d6_io);
1269	        GPIO_NUM_CHECK(slot_gpio->d7_io);
1270	    }
1271	
1272	    configure_pin(slot_gpio->clk_io, sdmmc_slot_gpio_sig[slot_id].clk, GPIO_MODE_OUTPUT, "clk", use_gpio_matrix);
1273	    configure_pin(slot_gpio->cmd_io, sdmmc_slot_gpio_sig[slot_id].cmd, GPIO_MODE_INPUT_OUTPUT, "cmd", use_gpio_matrix);
1274	    configure_pin(slot_gpio->d0_io, sdmmc_slot_gpio_sig[slot_id].d0, GPIO_MODE_INPUT_OUTPUT, "d0", use_gpio_matrix);
1275	
1276	    if (slot_width >= 4) {
1277	        configure_pin(slot_gpio->d1_io, sdmmc_slot_gpio_sig[slot_id].d1, GPIO_MODE_INPUT_OUTPUT, "d1", use_gpio_matrix);
1278	        configure_pin(slot_gpio->d2_io, sdmmc_slot_gpio_sig[slot_id].d2, GPIO_MODE_INPUT_OUTPUT, "d2", use_gpio_matrix);
1279	        if (slot->sd_mode == SD_MODE_UHS1) {
1280	            configure_pin(slot_gpio->d3_io, sdmmc_slot_gpio_sig[slot_id].d3, GPIO_MODE_INPUT_OUTPUT, "d3", use_gpio_matrix);
1281	        } else {
1282	            // Force D3 high to make slave enter SD mode.
1283	            // Connect to peripheral after width configuration.
1284	            if (slot_gpio->d3_io > GPIO_NUM_NC) {
1285	                gpio_config_t gpio_conf = {
1286	                    .pin_bit_mask = BIT64(slot_gpio->d3_io),
1287	                    .mode = GPIO_MODE_OUTPUT,
1288	                    .pull_up_en = GPIO_PULLUP_DISABLE,
1289	                    .pull_down_en = GPIO_PULLDOWN_DISABLE,
1290	                    .intr_type = GPIO_INTR_DISABLE,
1291	                };
1292	                gpio_config(&gpio_conf);
1293	                gpio_set_level(slot_gpio->d3_io, 1);
1294	            }
1295	        }
1296	    }
1297	    if (slot_width == 8) {
1298	        configure_pin(slot_gpio->d4_io, sdmmc_slot_gpio_sig[slot_id].d4, GPIO_MODE_INPUT_OUTPUT, "d4", use_gpio_matrix);
1299	        configure_pin(slot_gpio->d5_io, sdmmc_slot_gpio_sig[slot_id].d5, GPIO_MODE_INPUT_OUTPUT, "d5", use_gpio_matrix);
1300	        configure_pin(slot_gpio->d6_io, sdmmc_slot_gpio_sig[slot_id].d6, GPIO_MODE_INPUT_OUTPUT, "d6", use_gpio_matrix);
1301	        configure_pin(slot_gpio->d7_io, sdmmc_slot_gpio_sig[slot_id].d7, GPIO_MODE_INPUT_OUTPUT, "d7", use_gpio_matrix);
1302	    }
1303	
1304	    // SDIO slave interrupt is edge sensitive to ~(int_n | card_int | card_detect)
1305	    // set this and card_detect to high to enable sdio interrupt
1306	    esp_rom_gpio_connect_in_signal(GPIO_MATRIX_CONST_ONE_INPUT, slot_info->card_int, false);
1307	
1308	    // Set up Card Detect input
1309	    int matrix_in_cd = 0;
1310	    if (io_config->cd_io != GPIO_NUM_NC) {
1311	        ESP_LOGD(TAG, "using GPIO%d as CD pin", io_config->cd_io);
1312	        esp_rom_gpio_pad_select_gpio(io_config->cd_io);
1313	        gpio_set_direction(io_config->cd_io, GPIO_MODE_INPUT);
1314	        matrix_in_cd = io_config->cd_io;
1315	    } else {
1316	        // if not set, default to CD low (card present)
1317	        matrix_in_cd = GPIO_MATRIX_CONST_ZERO_INPUT;
1318	    }
1319	    esp_rom_gpio_connect_in_signal(matrix_in_cd, slot_info->card_detect, false);
1320	
1321	    // Set up Write Protect input
1322	    int matrix_in_wp;
1323	    if (io_config->wp_io != GPIO_NUM_NC) {
1324	        ESP_LOGD(TAG, "using GPIO%d as WP pin", io_config->wp_io);
1325	        esp_rom_gpio_pad_select_gpio(io_config->wp_io);
1326	        gpio_set_direction(io_config->wp_io, GPIO_MODE_INPUT);
1327	        matrix_in_wp = io_config->wp_io;
1328	    } else {
1329	        // if not set, default to WP high (not write protected)
1330	        matrix_in_wp = GPIO_MATRIX_CONST_ONE_INPUT;
1331	    }
1332	    // As hardware expects an active-high signal,
1333	    // if WP signal is active low, then invert it in GPIO matrix,
1334	    // else keep it in its default state
1335	    esp_rom_gpio_connect_in_signal(matrix_in_wp, slot_info->write_protect, (gpio_wp_polarity ? false : true));
1336	
1337	    return ESP_OK;
1338	}
