47	static void handle_voltage_switch_stage1(sd_host_sdmmc_slot_t *slot, sdmmc_command_t* cmd)
48	{
49	    ESP_LOGV(TAG, "%s: enabling clock", __func__);
50	    sd_host_slot_set_cclk_always_on_internal(slot, true);
51	}
52	
53	static void handle_voltage_switch_stage2(sd_host_sdmmc_slot_t *slot, sdmmc_command_t* cmd)
54	{
55	    ESP_LOGV(TAG, "%s: disabling clock", __func__);
56	    sd_host_slot_enable_clk_cmd11(slot, false);
57	    usleep(100);
58	    ESP_LOGV(TAG, "%s: switching voltage", __func__);
59	    esp_err_t err = cmd->volt_switch_cb(cmd->volt_switch_cb_arg, 1800);
60	    if (err != ESP_OK) {
61	        ESP_LOGE(TAG, "failed to switch voltage (0x%x)", err);
62	        cmd->error = err;
63	    }
64	    ESP_LOGV(TAG, "%s: waiting 10ms", __func__);
65	    usleep(10000);
66	    ESP_LOGV(TAG, "%s: enabling clock", __func__);
67	    sd_host_slot_enable_clk_cmd11(slot, true);
68	}
69	
70	static void handle_voltage_switch_stage3(sd_host_sdmmc_slot_t *slot, sdmmc_command_t* cmd)
71	{
72	    ESP_LOGV(TAG, "%s: voltage switch complete, clock back to low-power mode", __func__);
73	    sd_host_slot_set_cclk_always_on_internal(slot, false);
74	}
