78	---------------------------------------------------------------*/
79	size_t sd_host_get_free_descriptors_count(sd_host_sdmmc_slot_t *slot)
80	{
81	    const size_t next = slot->ctlr->cur_transfer.next_desc;
82	    size_t count = 0;
83	    /* Starting with the current DMA descriptor, count the number of
84	     * descriptors which have 'owned_by_idmac' set to 0. These are the
85	     * descriptors already processed by the DMA engine.
86	     */
87	    int dma_desc_num = slot->ctlr->dma_desc_num;
88	    for (size_t i = 0; i < dma_desc_num; ++i) {
89	        sdmmc_desc_t *desc = slot->ctlr->dma_desc + ((next + i) % dma_desc_num);
90	#if SOC_CACHE_INTERNAL_MEM_VIA_L1CACHE
91	        esp_err_t ret = esp_cache_msync((void *)desc, sizeof(sdmmc_desc_t), ESP_CACHE_MSYNC_FLAG_DIR_M2C);
92	        assert(ret == ESP_OK);
93	        (void)ret;
94	#endif
95	        if (desc->owned_by_idmac) {
96	            break;
97	        }
98	        ++count;
99	        if (desc->next_desc_ptr == NULL) {
100	            /* final descriptor in the chain */
101	            break;
102	        }
103	    }
104	    return count;
105	}
106	
107	void sd_host_fill_dma_descriptors(sd_host_sdmmc_slot_t *slot, size_t num_desc)
108	{
109	    sd_host_sdmmc_trans_state_t *cur_trans = &slot->ctlr->cur_transfer;
110	    for (size_t i = 0; i < num_desc; ++i) {
111	        if (cur_trans->size_remaining == 0) {
112	            return;
113	        }
114	        const size_t next = cur_trans->next_desc;
115	        sdmmc_desc_t *desc = slot->ctlr->dma_desc + next;
116	        assert(!desc->owned_by_idmac);
117	        size_t size_to_fill =
118	            (cur_trans->size_remaining < SDMMC_DMA_MAX_BUF_LEN) ?
119	            cur_trans->size_remaining : SDMMC_DMA_MAX_BUF_LEN;
120	        bool last = size_to_fill == cur_trans->size_remaining;
121	        desc->last_descriptor = last;
122	        desc->second_address_chained = 1;
123	        desc->owned_by_idmac = 1;
124	        desc->buffer1_ptr = cur_trans->ptr;
125	        desc->next_desc_ptr = (last) ? NULL : slot->ctlr->dma_desc + ((next + 1) % num_desc);
126	        assert(size_to_fill < 4 || size_to_fill % 4 == 0);
127	        desc->buffer1_size = (size_to_fill + 3) & (~3);
128	
129	        cur_trans->size_remaining -= size_to_fill;
130	        cur_trans->ptr += size_to_fill;
131	        cur_trans->next_desc = (cur_trans->next_desc + 1) % num_desc;
132	        ESP_LOGV(TAG, "fill %d desc=%d rem=%d next=%d last=%d sz=%d",
133	                 num_desc, next, cur_trans->size_remaining,
134	                 cur_trans->next_desc, desc->last_descriptor, desc->buffer1_size);
135	#if SOC_CACHE_INTERNAL_MEM_VIA_L1CACHE
136	        esp_err_t ret = esp_cache_msync((void *)desc, sizeof(sdmmc_desc_t), ESP_CACHE_MSYNC_FLAG_DIR_C2M);
137	        assert(ret == ESP_OK);
138	        (void)ret;
139	#endif
140	    }
141	}
