153	void sd_host_dma_prepare(sd_host_sdmmc_slot_t *slot, void *data_ptr, size_t data_size, size_t block_size)
154	{
155	    // this clears "owned by IDMAC" bits
156	    memset(slot->ctlr->dma_desc, 0, sizeof(sdmmc_desc_t) * slot->ctlr->dma_desc_num);
157	    // initialize first descriptor
158	    sdmmc_desc_t *desc = slot->ctlr->dma_desc;
159	    desc->first_descriptor = 1;
160	    // save transfer info
161	    slot->ctlr->cur_transfer.ptr = data_ptr;
162	    slot->ctlr->cur_transfer.size_remaining = data_size;
163	    slot->ctlr->cur_transfer.next_desc = 0;
164	    slot->ctlr->cur_transfer.desc_remaining = (data_size + SDMMC_DMA_MAX_BUF_LEN - 1) / SDMMC_DMA_MAX_BUF_LEN;
165	    // prepare descriptors
166	    sd_host_fill_dma_descriptors(slot, slot->ctlr->dma_desc_num);
167	
168	    // Set size of data and DMA descriptor pointer
169	    sdmmc_ll_set_data_transfer_len(slot->ctlr->hal.dev, data_size);
170	    sdmmc_ll_set_block_size(slot->ctlr->hal.dev, block_size);
171	    sdmmc_ll_set_desc_addr(slot->ctlr->hal.dev, (uint32_t)desc);
172	    // Enable everything needed to use DMA
173	    sdmmc_ll_enable_dma(slot->ctlr->hal.dev, true);
174	    sd_host_dma_resume(slot);
175	}
