177	/*---------------------------------------------------------------
178	                    CMD
179	---------------------------------------------------------------*/
180	static bool cmd_needs_auto_stop(const sdmmc_command_t *cmd)
181	{
182	    /* SDMMC host needs an "auto stop" flag for the following commands: */
183	    return cmd->datalen > 0 &&
184	           (cmd->opcode == MMC_WRITE_BLOCK_MULTIPLE ||
185	            cmd->opcode == MMC_READ_BLOCK_MULTIPLE ||
186	            cmd->opcode == MMC_WRITE_DAT_UNTIL_STOP ||
187	            cmd->opcode == MMC_READ_DAT_UNTIL_STOP);
188	}
189	
190	static sdmmc_hw_cmd_t make_hw_cmd(sdmmc_command_t *cmd)
191	{
192	    sdmmc_hw_cmd_t res = { 0 };
193	
194	    res.cmd_index = cmd->opcode;
195	    if (cmd->opcode == MMC_STOP_TRANSMISSION) {
196	        res.stop_abort_cmd = 1;
197	    } else if (cmd->opcode == MMC_GO_IDLE_STATE) {
198	        res.send_init = 1;
199	    } else if (cmd->opcode == SD_SWITCH_VOLTAGE) {
200	        res.volt_switch = 1;
201	    } else {
202	        res.wait_complete = 1;
203	    }
204	    if (cmd->opcode == MMC_GO_IDLE_STATE) {
205	        res.send_init = 1;
206	    }
207	
208	    if (cmd->flags & SCF_RSP_PRESENT) {
209	        res.response_expect = 1;
210	        if (cmd->flags & SCF_RSP_136) {
211	            res.response_long = 1;
212	        }
213	    }
214	    if (cmd->flags & SCF_RSP_CRC) {
215	        res.check_response_crc = 1;
216	    }
217	    if (cmd->data) {
218	        res.data_expected = 1;
219	        if ((cmd->flags & SCF_CMD_READ) == 0) {
220	            res.rw = 1;
221	        }
222	        assert(cmd->datalen % cmd->blklen == 0);
223	        res.send_auto_stop = cmd_needs_auto_stop(cmd) ? 1 : 0;
224	    }
225	    ESP_LOGV(TAG, "%s: opcode=%d, rexp=%d, crc=%d, auto_stop=%d", __func__,
226	             res.cmd_index, res.response_expect, res.check_response_crc,
227	             res.send_auto_stop);
228	    return res;
229	}
230	
231	static inline bool mask_check_and_clear(uint32_t *state, uint32_t mask)
232	{
233	    bool ret = ((*state) & mask) != 0;
234	    *state &= ~mask;
235	    return ret;
236	}
237	
238	static void process_command_response(sd_host_sdmmc_slot_t *slot, uint32_t status, sdmmc_command_t *cmd)
239	{
240	    if (cmd->flags & SCF_RSP_PRESENT) {
241	        if (cmd->flags & SCF_RSP_136) {
242	            /* Destination is 4-byte aligned, can memcopy from peripheral registers */
243	            memcpy(cmd->response, (uint32_t*) SDMMC.resp, 4 * sizeof(uint32_t));
244	        } else {
245	            cmd->response[0] = SDMMC.resp[0];
246	            cmd->response[1] = 0;
247	            cmd->response[2] = 0;
248	            cmd->response[3] = 0;
249	        }
250	    }
251	    esp_err_t err = ESP_OK;
252	    if (status & SDMMC_INTMASK_RTO) {
253	        // response timeout is only possible when response is expected
254	        assert(cmd->flags & SCF_RSP_PRESENT);
255	        err = ESP_ERR_TIMEOUT;
256	    } else if ((cmd->flags & SCF_RSP_CRC) && (status & SDMMC_INTMASK_RCRC)) {
257	        err = ESP_ERR_INVALID_CRC;
258	    } else if (status & SDMMC_INTMASK_RESP_ERR) {
259	        err = ESP_ERR_INVALID_RESPONSE;
260	    }
261	    if (err != ESP_OK) {
262	        cmd->error = err;
263	        if (cmd->data) {
264	            sd_host_dma_stop(slot);
265	        }
266	        ESP_LOGD(TAG, "%s: error 0x%x  (status=%08"PRIx32")", __func__, err, status);
267	    }
268	}
