271	                    Events
272	---------------------------------------------------------------*/
273	static esp_err_t sd_host_wait_for_event(sd_host_sdmmc_slot_t *slot, int tick_count, sd_host_sdmmc_event_t *out_event)
274	{
275	    assert(out_event);
276	    assert(slot->ctlr->event_queue);
277	
278	    int ret = xQueueReceive(slot->ctlr->event_queue, out_event, tick_count);
279	    if (ret == pdFALSE) {
280	        return ESP_ERR_TIMEOUT;
281	    }
282	    return ESP_OK;
283	}
284	
285	static esp_err_t sd_host_handle_idle_state_events(sd_host_sdmmc_slot_t *slot)
286	{
287	    /* Handle any events which have happened in between transfers.
288	     * Under current assumptions (no SDIO support) only card detect events
289	     * can happen in the idle state.
290	     */
291	    sd_host_sdmmc_event_t evt;
292	    while (sd_host_wait_for_event(slot, 0, &evt) == ESP_OK) {
293	        if (evt.sdmmc_status & SDMMC_INTMASK_CD) {
294	            ESP_LOGV(TAG, "card detect event");
295	            evt.sdmmc_status &= ~SDMMC_INTMASK_CD;
296	        }
297	        if (evt.sdmmc_status != 0 || evt.dma_status != 0) {
298	            ESP_LOGE(TAG, "handle_idle_state_events unhandled: %08"PRIx32" %08"PRIx32,
299	                     evt.sdmmc_status, evt.dma_status);
300	        }
301	
302	    }
303	    return ESP_OK;
304	}
305	
306	static void process_data_status(sd_host_sdmmc_slot_t *slot, uint32_t status, sdmmc_command_t *cmd)
307	{
308	    if (status & SD_DATA_ERR_MASK) {
309	        if (status & SDMMC_INTMASK_DTO) {
310	            cmd->error = ESP_ERR_TIMEOUT;
311	        } else if (status & SDMMC_INTMASK_DCRC) {
312	            cmd->error = ESP_ERR_INVALID_CRC;
313	        } else if ((status & SDMMC_INTMASK_EBE) &&
314	                   (cmd->flags & SCF_CMD_READ) == 0) {
315	            cmd->error = ESP_ERR_TIMEOUT;
316	        } else {
317	            cmd->error = ESP_FAIL;
318	        }
319	        SDMMC.ctrl.fifo_reset = 1;
320	    }
321	    if (cmd->error != 0) {
322	        if (cmd->data) {
323	            sd_host_dma_stop(slot);
324	        }
325	        ESP_LOGD(TAG, "%s: error 0x%x (status=%08"PRIx32")", __func__, cmd->error, status);
326	    }
327	
328	}
329	
330	static esp_err_t process_events(sd_host_sdmmc_slot_t *slot, sd_host_sdmmc_event_t evt, sdmmc_command_t *cmd,
331	                                sdmmc_req_state_t *pstate, sd_host_sdmmc_event_t *unhandled_events)
332	{
333	    const char* const s_state_names[] __attribute__((unused)) = {
334	        "IDLE",
335	        "SENDING_CMD",
336	        "SENDIND_DATA",
337	        "BUSY",
338	        "SENDING_VOLTAGE_SWITCH",
339	        "WAITING_VOLTAGE_SWITCH",
340	    };
341	    sd_host_sdmmc_event_t orig_evt = evt;
342	    ESP_LOGV(TAG, "%s: slot_id=%d state=%s evt=%"PRIx32" dma=%"PRIx32, __func__, slot->slot_id,
343	             s_state_names[*pstate], evt.sdmmc_status, evt.dma_status);
344	    sdmmc_req_state_t next_state = *pstate;
345	    sdmmc_req_state_t state = (sdmmc_req_state_t) -1;
346	    while (next_state != state) {
347	        state = next_state;
348	        switch (state) {
349	        case SDMMC_IDLE:
350	            break;
351	
352	        case SDMMC_SENDING_CMD:
353	            if (mask_check_and_clear(&evt.sdmmc_status, SD_CMD_ERR_MASK)) {
354	                process_command_response(slot, orig_evt.sdmmc_status, cmd);
355	                // In addition to the error interrupt, CMD_DONE will also be
356	                // reported. It may occur immediately (in the same sd_host_sdmmc_event_t) or
357	                // be delayed until the next interrupt.
358	            }
359	            if (mask_check_and_clear(&evt.sdmmc_status, SDMMC_INTMASK_CMD_DONE)) {
360	                process_command_response(slot, orig_evt.sdmmc_status, cmd);
361	                if (cmd->error != ESP_OK) {
362	                    next_state = SDMMC_IDLE;
363	                    break;
364	                }
365	
366	                if (cmd->data == NULL) {
367	                    next_state = SDMMC_IDLE;
368	                } else {
369	                    next_state = SDMMC_SENDING_DATA;
370	                }
371	            }
372	            break;
373	
374	        case SDMMC_SENDING_VOLTAGE_SWITCH:
375	            if (mask_check_and_clear(&evt.sdmmc_status, SD_CMD_ERR_MASK)) {
376	                process_command_response(slot, orig_evt.sdmmc_status, cmd);
377	                next_state = SDMMC_IDLE;
378	            }
379	            if (mask_check_and_clear(&evt.sdmmc_status, SDMMC_INTMASK_VOLT_SW)) {
380	                handle_voltage_switch_stage2(slot, cmd);
381	                if (cmd->error != ESP_OK) {
382	                    next_state = SDMMC_IDLE;
383	                } else {
384	                    next_state = SDMMC_WAITING_VOLTAGE_SWITCH;
385	                }
386	            }
387	            break;
388	
389	        case SDMMC_WAITING_VOLTAGE_SWITCH:
390	            if (mask_check_and_clear(&evt.sdmmc_status, SD_CMD_ERR_MASK)) {
391	                process_command_response(slot, orig_evt.sdmmc_status, cmd);
392	                next_state = SDMMC_IDLE;
393	            }
394	            if (mask_check_and_clear(&evt.sdmmc_status, SDMMC_INTMASK_VOLT_SW)) {
395	                handle_voltage_switch_stage3(slot, cmd);
396	                next_state = SDMMC_IDLE;
397	            }
398	            break;
399	
400	        case SDMMC_SENDING_DATA:
401	            if (mask_check_and_clear(&evt.sdmmc_status, SD_DATA_ERR_MASK)) {
402	                process_data_status(slot, orig_evt.sdmmc_status, cmd);
403	                sd_host_dma_stop(slot);
404	            }
405	            if (mask_check_and_clear(&evt.dma_status, SD_DMA_DONE_MASK)) {
406	                next_state = SDMMC_BUSY;
407	            }
408	            if (orig_evt.sdmmc_status & (SDMMC_INTMASK_SBE | SDMMC_INTMASK_DATA_OVER)) {
409	                // On start bit error, DATA_DONE interrupt will not be generated
410	                next_state = SDMMC_IDLE;
411	                break;
412	            }
413	            break;
414	
415	        case SDMMC_BUSY:
416	            if (!mask_check_and_clear(&evt.sdmmc_status, SDMMC_INTMASK_DATA_OVER)) {
417	                break;
418	            }
419	            process_data_status(slot, orig_evt.sdmmc_status, cmd);
420	            next_state = SDMMC_IDLE;
421	            break;
422	        }
423	        ESP_LOGV(TAG, "%s state=%s next_state=%s", __func__, s_state_names[state], s_state_names[next_state]);
424	    }
425	    *pstate = state;
426	    *unhandled_events = evt;
427	    return ESP_OK;
428	}
429	
430	static esp_err_t handle_event(sd_host_sdmmc_slot_t *slot, sdmmc_command_t* cmd, sdmmc_req_state_t *state,
431	                              sd_host_sdmmc_event_t *unhandled_events)
432	{
433	    sd_host_sdmmc_event_t event;
434	    esp_err_t err = sd_host_wait_for_event(slot, cmd->timeout_ms / portTICK_PERIOD_MS, &event);
435	    if (err != ESP_OK) {
436	        ESP_LOGE(TAG, "sd_host_wait_for_event returned 0x%x", err);
437	        if (err == ESP_ERR_TIMEOUT) {
438	            sd_host_dma_stop(slot);
439	        }
440	        return err;
441	    }
442	    ESP_LOGV(TAG, "sdmmc_handle_event: slot_id %d event %08"PRIx32" %08"PRIx32", unhandled %08"PRIx32" %08"PRIx32,
443	             slot->slot_id, event.sdmmc_status, event.dma_status,
444	             unhandled_events->sdmmc_status, unhandled_events->dma_status);
445	    event.sdmmc_status |= unhandled_events->sdmmc_status;
446	    event.dma_status |= unhandled_events->dma_status;
447	    process_events(slot, event, cmd, state, unhandled_events);
448	    ESP_LOGV(TAG, "sdmmc_handle_event: slot_id %d events unhandled: %08"PRIx32" %08"PRIx32, slot->slot_id, unhandled_events->sdmmc_status, unhandled_events->dma_status);
449	    return ESP_OK;
450	}
451	
452	static bool sd_host_card_busy(sd_host_sdmmc_slot_t *slot)
453	{
454	    return sdmmc_ll_is_card_data_busy(slot->ctlr->hal.dev);
455	}
456	
457	static bool wait_for_busy_cleared(sd_host_sdmmc_slot_t *slot, uint32_t timeout_ms)
458	{
459	    if (timeout_ms == 0) {
460	        return !sd_host_card_busy(slot);
461	    }
462	
463	    /* It would have been nice to do this without polling, however the peripheral
464	     * can only generate Busy Clear Interrupt for data write commands, and waiting
465	     * for busy clear is mostly needed for other commands such as MMC_SWITCH.
466	     */
467	    uint32_t timeout_ticks = (timeout_ms + portTICK_PERIOD_MS - 1) / portTICK_PERIOD_MS;
468	    while (timeout_ticks-- > 0) {
469	        if (!sd_host_card_busy(slot)) {
470	            return true;
471	        }
472	        vTaskDelay(1);
473	    }
474	    return false;
475	}
