477	/*---------------------------------------------------------------
478	                    Public API Impl
479	---------------------------------------------------------------*/
480	esp_err_t sd_host_slot_sdmmc_do_transaction(sd_host_slot_handle_t slot, sdmmc_command_t *cmdinfo)
481	{
482	    esp_err_t ret = ESP_FAIL;
483	    ESP_RETURN_ON_FALSE(slot && cmdinfo, ESP_ERR_INVALID_ARG, TAG, "invalid argument: null pointer");
484	    sd_host_sdmmc_slot_t *slot_ctx = __containerof(slot, sd_host_sdmmc_slot_t, drv);
485	
486	    xSemaphoreTake(slot_ctx->ctlr->mutex, portMAX_DELAY);
487	#if CONFIG_PM_ENABLE
488	    if (slot_ctx->ctlr->pm_lock) {
489	        ESP_GOTO_ON_ERROR(esp_pm_lock_acquire(slot_ctx->ctlr->pm_lock), out, TAG, "acquire pm_lock failed");
490	    }
491	#endif
492	    slot_ctx->ctlr->cur_slot_id = slot_ctx->slot_id;
493	
494	    // By default, set probing frequency (400kHz) and 1-bit bus
495	    if (slot_ctx->freq.freq_state != SD_HOST_SLOT_STATE_READY) {
496	        ESP_GOTO_ON_ERROR(sd_host_slot_set_card_clk(slot_ctx), out, TAG, "failed to set clk");
497	    } else {
498	        int real_freq_khz = 0;
499	        ret = sd_host_slot_get_real_freq(slot_ctx, &real_freq_khz);
500	        assert(ret == ESP_OK);
501	        if (real_freq_khz != (slot_ctx->freq.freq_hz / 1000)) {
502	            ESP_GOTO_ON_ERROR(sd_host_slot_set_card_clk(slot_ctx), out, TAG, "failed to set clk");
503	        }
504	    }
505	    ESP_GOTO_ON_ERROR(sd_host_slot_set_bus_width(slot_ctx), out, TAG, "failed to set width");
506	    ESP_GOTO_ON_ERROR(sd_host_slot_set_bus_sampling_mode(slot_ctx), out, TAG, "failed to set sampling mode");
507	    ESP_GOTO_ON_ERROR(sd_host_set_delay_phase(slot_ctx), out, TAG, "failed to set delay phase");
508	    ESP_GOTO_ON_ERROR(sd_host_set_delay_line(slot_ctx), out, TAG, "failed to set delay line");
509	
510	#if SOC_CACHE_INTERNAL_MEM_VIA_L1CACHE
511	    // cache sync related
512	    size_t cache_sync_len = 0;
513	#endif
514	
515	    // dispose of any events which happened asynchronously
516	    sd_host_handle_idle_state_events(slot_ctx);
517	
518	    // special handling for voltage switch command
519	    if (cmdinfo->opcode == SD_SWITCH_VOLTAGE) {
520	        handle_voltage_switch_stage1(slot_ctx, cmdinfo);
521	    }
522	
523	    // convert cmdinfo to hardware register value
524	    sdmmc_hw_cmd_t hw_cmd = make_hw_cmd(cmdinfo);
525	    if (cmdinfo->data) {
526	        // Length should be either <4 or >=4 and =0 (mod 4).
527	        if (cmdinfo->datalen >= 4 && cmdinfo->datalen % 4 != 0) {
528	            ESP_LOGE(TAG, "%s: invalid size: total=%d",
529	                     __func__, cmdinfo->datalen);
530	            ret = ESP_ERR_INVALID_SIZE;
531	            goto out;
532	        }
533	
534	        bool is_aligned = sd_host_check_buffer_alignment(slot_ctx, cmdinfo->data, cmdinfo->buflen);
535	        if (!is_aligned) {
536	            ESP_LOGE(TAG, "%s: buffer %p can not be used for DMA", __func__, cmdinfo->data);
537	            ret = ESP_ERR_INVALID_ARG;
538	            goto out;
539	        }
540	
541	#if SOC_CACHE_INTERNAL_MEM_VIA_L1CACHE
542	        cache_sync_len = cmdinfo->buflen;
543	        ret = esp_cache_msync((void *)cmdinfo->data, cache_sync_len, ESP_CACHE_MSYNC_FLAG_DIR_C2M);
544	        if (ret != ESP_OK) {
545	            goto out;
546	        }
547	#endif
548	        // write transfer info into hardware
549	        sd_host_dma_prepare(slot_ctx, cmdinfo->data, cmdinfo->datalen, cmdinfo->blklen);
550	    }
551	    // write command into hardware, this also sends the command to the card
552	    ret = sd_host_slot_start_command(slot_ctx, hw_cmd, cmdinfo->arg);
553	    if (ret != ESP_OK) {
554	        goto out;
555	    }
556	    // process events until transfer is complete
557	    cmdinfo->error = ESP_OK;
558	    sdmmc_req_state_t state = SDMMC_SENDING_CMD;
559	    if (cmdinfo->opcode == SD_SWITCH_VOLTAGE) {
560	        state = SDMMC_SENDING_VOLTAGE_SWITCH;
561	    }
562	    sd_host_sdmmc_event_t unhandled_events = {};
563	    while (state != SDMMC_IDLE) {
564	        ret = handle_event(slot_ctx, cmdinfo, &state, &unhandled_events);
565	        if (ret != ESP_OK) {
566	            break;
567	        }
568	    }
569	    if (ret == ESP_OK && (cmdinfo->flags & SCF_WAIT_BUSY)) {
570	        if (!wait_for_busy_cleared(slot_ctx, cmdinfo->timeout_ms)) {
571	            ret = ESP_ERR_TIMEOUT;
572	        }
573	    }
574	    slot_ctx->ctlr->is_app_cmd = (ret == ESP_OK && cmdinfo->opcode == MMC_APP_CMD);
575	
576	#if SOC_CACHE_INTERNAL_MEM_VIA_L1CACHE
577	    if (cmdinfo->data) {
578	        ret = esp_cache_msync((void *)cmdinfo->data, cache_sync_len, ESP_CACHE_MSYNC_FLAG_DIR_M2C);
579	        if (ret != ESP_OK) {
580	            goto out;
581	        }
582	    }
583	#endif
584	
585	out:
586	#if CONFIG_PM_ENABLE
587	    if (slot_ctx->ctlr->pm_lock) {
588	        ESP_RETURN_ON_ERROR(esp_pm_lock_release(slot_ctx->ctlr->pm_lock), TAG, "release pm_lock failed");
589	    }
590	#endif
591	    xSemaphoreGive(slot_ctx->ctlr->mutex);
592	
593	    return ret;
594	}
