#include <nuttx/mutex.h>

#include "esp_sdmmc.h"
#include "esp_gpio.h"
#include "esp_irq.h"

#ifdef CONFIG_ESP32P4_SDMMC_LDO
#  include "esp_ldo.h"
#endif

#include "hal/sdmmc_ll.h"
#include "hal/sd_types.h"
#include "soc/sdmmc_struct.h"
#include "soc/sdmmc_reg.h"
#include "soc/interrupts.h"

/* ========================================================================
 * 全局状态
 * ======================================================================== */

#define __DECLARE_RCC_ATOMIC_ENV  0

static struct esp32p4_sdmmc_state_s g_sdmmc_state[2];

/* ========================================================================
 * Cache 操作
 * ======================================================================== */

#ifdef up_invalidate_dcache
#  define SDMMC_INV_DCACHE(s, e)  up_invalidate_dcache((s), (e))
#else
#  define SDMMC_INV_DCACHE(s, e)  do { } while (0)
#endif

#ifdef up_clean_dcache
#  define SDMMC_CLN_DCACHE(s, e)  up_clean_dcache((s), (e))
#else
#  define SDMMC_CLN_DCACHE(s, e)  do { } while (0)
#endif

/* ========================================================================
 * 辅助宏
 * ======================================================================== */

#define SDMMC_SRC_CLK_KHZ       160000  /* PLL160M */

/* ========================================================================
 * 调试宏 - 使用 printf 输出调试信息
 * ======================================================================== */

#define SDMMC_DEBUG 1

#if SDMMC_DEBUG
#  define sdmmc_dbg(fmt, ...) \
  printf("[SDMMC] " fmt "\n", ##__VA_ARGS__)
#  define sdmmc_err(fmt, ...) \
  printf("[SDMMC ERROR] %s:%d " fmt "\n", __func__, __LINE__, ##__VA_ARGS__)
#else
#  define sdmmc_dbg(fmt, ...)  do { } while (0)
#  define sdmmc_err(fmt, ...)  do { } while (0)
#endif

/* ========================================================================
 * LDO
 * ======================================================================== */

#ifdef CONFIG_ESP32P4_SDMMC_LDO

static int esp32p4_sdmmc_ldo_init(struct esp32p4_sdmmc_state_s *state)
{
  struct esp_ldo_config_t *ldo;

  if (state->slot != 0)
    {
      return OK;
    }

  ldo = kmm_malloc(sizeof(struct esp_ldo_config_t));
  if (ldo == NULL)
    {
      sdmmc_err("LDO malloc failed");
      return -ENOMEM;
    }

  memset(ldo, 0, sizeof(*ldo));
  ldo->chan_id    = CONFIG_ESP32P4_SDMMC_LDO_CHAN;
  ldo->voltage_mv = CONFIG_ESP32P4_SDMMC_LDO_VOLTAGE;

  sdmmc_dbg("LDO init: chan=%d voltage=%dmV", ldo->chan_id, ldo->voltage_mv);

  int ret = esp_ldo_channel_acquire(ldo);
  if (ret < 0)
    {
      kmm_free(ldo);
      sdmmc_err("LDO acquire failed: %d", ret);
      return ret;
    }

  state->ldo_config = ldo;
  sdmmc_dbg("LDO OK: chan=%d @ %dmV", ldo->chan_id, ldo->voltage_mv);
  return OK;
}

static void esp32p4_sdmmc_ldo_deinit(struct esp32p4_sdmmc_state_s *state)
{
  struct esp_ldo_config_t *ldo = state->ldo_config;

  if (ldo != NULL)
    {
      esp_ldo_channel_release(ldo);
      kmm_free(ldo);
      state->ldo_config = NULL;
    }
}

#else

static int esp32p4_sdmmc_ldo_init(struct esp32p4_sdmmc_state_s *state)
{
  sdmmc_dbg("LDO disabled in config");
  return OK;
}

static void esp32p4_sdmmc_ldo_deinit(struct esp32p4_sdmmc_state_s *state)
{
}

#endif

/* ========================================================================
 * GPIO - 使用 IOMUX function0（与 HAL 一致）
 * ======================================================================== */

static int esp32p4_sdmmc_gpio_init(struct esp32p4_sdmmc_state_s *state)
{
  const int *pins;
  int npins;
  int i;

  sdmmc_dbg("GPIO init slot=%d", state->slot);

  if (state->slot == 0)
    {
      static const int slot0_pins[] =
      {
        ESP32P4_SDMMC0_CLK, ESP32P4_SDMMC0_CMD,
        ESP32P4_SDMMC0_D0,  ESP32P4_SDMMC0_D1,
        ESP32P4_SDMMC0_D2,  ESP32P4_SDMMC0_D3,
      };
      pins  = slot0_pins;
      npins = 6;

      sdmmc_dbg("Slot0 pins: CLK=%d CMD=%d D0=%d D1=%d D2=%d D3=%d",
                ESP32P4_SDMMC0_CLK, ESP32P4_SDMMC0_CMD,
                ESP32P4_SDMMC0_D0, ESP32P4_SDMMC0_D1,
                ESP32P4_SDMMC0_D2, ESP32P4_SDMMC0_D3);
    }
  else
    {
#ifdef CONFIG_ESP32P4_SDMMC_SLOT1
      static const int slot1_pins[] =
      {
        CONFIG_ESP32P4_SDMMC_SLOT1_CLK,
        CONFIG_ESP32P4_SDMMC_SLOT1_CMD,
        CONFIG_ESP32P4_SDMMC_SLOT1_D0,
        CONFIG_ESP32P4_SDMMC_SLOT1_D1,
        CONFIG_ESP32P4_SDMMC_SLOT1_D2,
        CONFIG_ESP32P4_SDMMC_SLOT1_D3,
      };
      pins  = slot1_pins;
      npins = 6;
#else
      sdmmc_err("Slot1 not enabled");
      return -EINVAL;
#endif
    }

  for (i = 0; i < npins; i++)
    {
      gpio_pinattr_t attr;
      bool is_clk = false;

      if ((state->slot == 0 && pins[i] == ESP32P4_SDMMC0_CLK) ||
          (state->slot == 1
#ifdef CONFIG_ESP32P4_SDMMC_SLOT1
           && pins[i] == CONFIG_ESP32P4_SDMMC_SLOT1_CLK
#endif
          ))
        {
          is_clk = true;
        }

      /* Slot 0 使用 IOMUX function0（固定引脚），Slot 1 使用 GPIO Matrix */
      if (state->slot == 0)
        {
          /* IOMUX 模式：CLK 为输出，其他为输入输出 */
          if (is_clk)
            {
              attr = OUTPUT_FUNCTION_0 | PULLUP;
            }
          else
            {
              attr = INPUT_OUTPUT_FUNCTION_0 | PULLUP;
            }
        }
      else
        {
          /* GPIO Matrix 模式 */
          if (is_clk)
            {
              attr = OUTPUT_FUNCTION_1 | PULLUP;
            }
          else
            {
              attr = INPUT_FUNCTION_1 | PULLUP;
            }
        }

      sdmmc_dbg("  pin %d: attr=0x%x%s", pins[i], attr,
                is_clk ? " (CLK)" : "");
      esp_configgpio(pins[i], attr);
    }

#ifdef CONFIG_ESP32P4_SDMMC_SLOT1
  if (state->slot == 1)
    {
      sdmmc_dbg("Slot1 GPIO matrix routing");
      esp_gpio_matrix_out(CONFIG_ESP32P4_SDMMC_SLOT1_CLK,
                          SD_CARD_CCLK_2_PAD_OUT_IDX, false, false);
      esp_gpio_matrix_in(CONFIG_ESP32P4_SDMMC_SLOT1_CMD,
                         SD_CARD_CCMD_2_PAD_IN_IDX, false);
      esp_gpio_matrix_out(CONFIG_ESP32P4_SDMMC_SLOT1_CMD,
                          SD_CARD_CCMD_2_PAD_OUT_IDX, false, false);
      esp_gpio_matrix_in(CONFIG_ESP32P4_SDMMC_SLOT1_D0,
                         SD_CARD_CDATA0_2_PAD_IN_IDX, false);
      esp_gpio_matrix_out(CONFIG_ESP32P4_SDMMC_SLOT1_D0,
                          SD_CARD_CDATA0_2_PAD_OUT_IDX, false, false);
      esp_gpio_matrix_in(CONFIG_ESP32P4_SDMMC_SLOT1_D1,
                         SD_CARD_CDATA1_2_PAD_IN_IDX, false);
      esp_gpio_matrix_out(CONFIG_ESP32P4_SDMMC_SLOT1_D1,
                          SD_CARD_CDATA1_2_PAD_OUT_IDX, false, false);
      esp_gpio_matrix_in(CONFIG_ESP32P4_SDMMC_SLOT1_D2,
                         SD_CARD_CDATA2_2_PAD_IN_IDX, false);
      esp_gpio_matrix_out(CONFIG_ESP32P4_SDMMC_SLOT1_D2,
                          SD_CARD_CDATA2_2_PAD_OUT_IDX, false, false);
      esp_gpio_matrix_in(CONFIG_ESP32P4_SDMMC_SLOT1_D3,
                         SD_CARD_CDATA3_2_PAD_IN_IDX, false);
      esp_gpio_matrix_out(CONFIG_ESP32P4_SDMMC_SLOT1_D3,
                          SD_CARD_CDATA3_2_PAD_OUT_IDX, false, false);
    }
#endif

  sdmmc_dbg("Slot %d GPIO OK", state->slot);
  return OK;
}

/* ========================================================================
 * 中断
 * ======================================================================== */

static struct esp32p4_sdmmc_state_s *esp32p4_sdmmc_get_state(struct sdio_dev_s *dev)
{
  return (struct esp32p4_sdmmc_state_s *)dev;
}

static int esp32p4_sdmmc_interrupt(int irq, void *context, void *arg)
{
  struct esp32p4_sdmmc_state_s *state = arg;
  sdmmc_dev_t *hw = SDMMC_LL_GET_HW(0);
  uint32_t status;
  uint32_t idsts;

  status = sdmmc_ll_get_intr_status(hw);
  sdmmc_ll_clear_interrupt(hw, status);

  idsts = sdmmc_ll_get_idsts_interrupt_raw(hw);
  sdmmc_ll_clear_idsts_interrupt(hw, idsts);

  state->pending |= status;

  sdmmc_dbg("IRQ: status=0x%08lx idsts=0x%08lx",
            (unsigned long)status, (unsigned long)idsts);

  if (state->waitevents & status)
    {
      state->wkupevent = state->waitevents & status;
      nxsem_post(&state->sem);
    }

  return OK;
}

/* ========================================================================
 * 时钟控制 - 使用 HAL 的两阶段分频
 * ======================================================================== */

static void esp32p4_sdmmc_set_clock(struct esp32p4_sdmmc_state_s *state,
                                    uint32_t freq_khz)
{
  sdmmc_dev_t *hw = SDMMC_LL_GET_HW(0);
  int host_div;
  int card_div;

  sdmmc_dbg("set_clock: target=%lukHz", (unsigned long)freq_khz);

  /* 两阶段分频：host_div (1-16) + card_div (0-255)
   * 最终频率 = 160MHz / host_div / (card_div == 0 ? 1 : card_div*2)
   */

  if (freq_khz >= 40000)
    {
      /* High speed: 160MHz / 4 = 40MHz */
      host_div = 4;
      card_div = 0;
    }
  else if (freq_khz >= 20000)
    {
      /* Default speed: 160MHz / 8 = 20MHz */
      host_div = 8;
      card_div = 0;
    }
  else if (freq_khz >= 400)
    {
      /* Probing: 160MHz / 10 / (20*2) = 400kHz */
      host_div = 10;
      card_div = 20;
    }
  else
    {
      /* Custom low frequency */
      host_div = 2;
      card_div = (SDMMC_SRC_CLK_KHZ * 1000 / 2) / (2 * freq_khz * 1000);
    }

  /* 1. 关闭 card clock */
  sdmmc_ll_enable_card_clock(hw, state->slot, false);

  /* 2. 设置 host 时钟分频 */
  sdmmc_ll_set_clock_div(hw, host_div);

  /* 3. 设置 card 时钟分频 */
  sdmmc_ll_set_card_clock_div(hw, state->slot, card_div);

  /* 4. 发送 update_clk_reg 命令到 CIU（关键！） */
  {
    sdmmc_hw_cmd_t cmd = {0};
    cmd.update_clk_reg = 1;
    cmd.wait_complete = 1;
    cmd.card_num = state->slot;
    cmd.start_command = 1;

    sdmmc_ll_set_command_arg(hw, 0);
    sdmmc_ll_set_command(hw, cmd);

    /* 等待命令被 CIU 接受 */
    uint32_t timeout = 10000;
    while (!sdmmc_ll_is_command_taken(hw))
      {
        if (--timeout == 0)
          {
            sdmmc_err("update_clk timeout!");
            break;
          }
        up_udelay(1);
      }
  }

  /* 5. 重新使能 card clock */
  sdmmc_ll_enable_card_clock(hw, state->slot, true);

  /* 6. 再次发送 update_clk_reg 命令 */
  {
    sdmmc_hw_cmd_t cmd = {0};
    cmd.update_clk_reg = 1;
    cmd.wait_complete = 1;
    cmd.card_num = state->slot;
    cmd.start_command = 1;

    sdmmc_ll_set_command_arg(hw, 0);
    sdmmc_ll_set_command(hw, cmd);

    uint32_t timeout = 10000;
    while (!sdmmc_ll_is_command_taken(hw))
      {
        if (--timeout == 0)
          {
            sdmmc_err("update_clk2 timeout!");
            break;
          }
        up_udelay(1);
      }
  }

  /* 计算实际频率 */
  if (card_div == 0)
    {
      state->freq_khz = SDMMC_SRC_CLK_KHZ / host_div;
    }
  else
    {
      state->freq_khz = SDMMC_SRC_CLK_KHZ / host_div / (card_div * 2);
    }

  sdmmc_dbg("set_clock: host_div=%d card_div=%d actual=%lukHz",
            host_div, card_div, (unsigned long)state->freq_khz);
}

/* ========================================================================
 * 控制器复位（使用 LL 层）
 * ======================================================================== */

static void esp32p4_sdmmc_reset_controller(void)
{
  sdmmc_dev_t *hw = SDMMC_LL_GET_HW(0);
  uint32_t timeout;

  sdmmc_dbg("reset_controller");

  /* DMA 复位 */
  sdmmc_ll_reset_dma(hw);
  timeout = 10000;
  while (!sdmmc_ll_is_dma_reset_done(hw))
    {
      if (--timeout == 0)
        {
          sdmmc_err("DMA reset timeout!");
          break;
        }
      up_udelay(10);
    }

  /* FIFO 复位 */
  sdmmc_ll_reset_fifo(hw);
  timeout = 10000;
  while (!sdmmc_ll_is_fifo_reset_done(hw))
    {
      if (--timeout == 0)
        {
          sdmmc_err("FIFO reset timeout!");
          break;
        }
      up_udelay(10);
    }

  /* 控制器复位 */
  sdmmc_ll_reset_controller(hw);
  timeout = 10000;
  while (!sdmmc_ll_is_controller_reset_done(hw))
    {
      if (--timeout == 0)
        {
          sdmmc_err("Controller reset timeout!");
          break;
        }
      up_udelay(10);
    }

  /* 清除中断 */
  sdmmc_ll_clear_interrupt(hw, 0xFFFFFFFF);
  sdmmc_ll_clear_idsts_interrupt(hw, 0xFFFFFFFF);

  sdmmc_dbg("reset_controller done");
}

/* ========================================================================
 * 等待数据总线空闲
 * ======================================================================== */

static void esp32p4_sdmmc_wait_idle(void)
{
  sdmmc_dev_t *hw = SDMMC_LL_GET_HW(0);
  uint32_t timeout = 100000;

  while (sdmmc_ll_is_card_data_busy(hw) && --timeout)
    {
      up_udelay(1);
    }

  if (timeout == 0)
    {
      sdmmc_err("wait_idle timeout!");
    }
}

/* ========================================================================
 * DMA 描述符设置 - 使用 HAL 兼容的 sdmmc_desc_t 格式
 * ======================================================================== */

static void esp32p4_sdmmc_setup_dma(struct esp32p4_sdmmc_state_s *state,
                                    uint8_t *buffer, size_t nbytes, bool is_tx)
{
  sdmmc_dev_t *hw = SDMMC_LL_GET_HW(0);
  size_t desc_idx = 0;
  size_t remaining = nbytes;
  uint8_t *buf_ptr = buffer;

  sdmmc_dbg("setup_dma: buf=%p size=%zu %s", buffer, nbytes,
            is_tx ? "TX" : "RX");

  /* 清零所有描述符 */
  memset(state->dma_desc, 0, sizeof(state->dma_desc));

  while (remaining > 0 && desc_idx < SDMMC_DMA_DESC_NUM)
    {
      size_t chunk = remaining;
      if (chunk > 4096)
        {
          chunk = 4096;
        }

      struct esp32p4_sdmmc_dmadesc_s *desc = &state->dma_desc[desc_idx];

      /* 使用 HAL 兼容的描述符格式 */
      desc->ctrl = (1U << 13) |  /* first_descriptor */
                   (1U << 31);   /* owned_by_idmac */
      if (remaining <= 4096 || desc_idx == SDMMC_DMA_DESC_NUM - 1)
        {
          desc->ctrl |= (1U << 2);  /* last_descriptor */
        }

      desc->size = (chunk + 3) & (~3);  /* 对齐到 4 字节 */
      desc->buf_addr = (void *)buf_ptr;
      desc->next_desc = (remaining > 4096 && desc_idx < SDMMC_DMA_DESC_NUM - 1)
                        ? (void *)&state->dma_desc[desc_idx + 1]
                        : NULL;

      sdmmc_dbg("  desc[%zu]: ctrl=0x%08lx size=%lu buf=%p next=%p",
                desc_idx, (unsigned long)desc->ctrl,
                (unsigned long)desc->size, desc->buf_addr, desc->next_desc);

      buf_ptr += chunk;
      remaining -= chunk;
      desc_idx++;
    }

  /* Cache 操作 */
  SDMMC_INV_DCACHE((uintptr_t)state->dma_desc,
                   (uintptr_t)state->dma_desc + sizeof(state->dma_desc));

  if (!is_tx)
    {
      SDMMC_INV_DCACHE((uintptr_t)buffer, (uintptr_t)buffer + nbytes);
    }
  else
    {
      SDMMC_CLN_DCACHE((uintptr_t)buffer, (uintptr_t)buffer + nbytes);
    }

  /* 设置 DMA 描述符地址 */
  sdmmc_ll_set_desc_addr(hw, (uint32_t)&state->dma_desc[0]);
  sdmmc_dbg("DMA desc addr=0x%08lx", (unsigned long)&state->dma_desc[0]);

  /* 使能 DMA */
  sdmmc_ll_enable_dma(hw, true);

  /* Poll demand 启动 DMA */
  sdmmc_ll_poll_demand(hw);
}

