                                enum sdio_clock_e rate)
{
  struct esp32p4_sdmmc_state_s *state = esp32p4_sdmmc_get_state(dev);
  uint32_t freq;

  switch (rate)
    {
      case CLOCK_IDMODE:
        freq = 400;
        break;
      case CLOCK_MMC_TRANSFER:
      case CLOCK_SD_TRANSFER_1BIT:
        freq = 20000;
