      case CLOCK_SD_TRANSFER_4BIT:
        freq = 40000;
        break;
      default:
        freq = 20000;
        break;
    }

  sdmmc_dbg("clock: rate=%d -> freq=%lukHz", rate, (unsigned long)freq);
  esp32p4_sdmmc_set_clock(state, freq);
}

