              return -EIO;
            }
        }

      if ((status & SDMMC_LL_EVENT_DATA_OVER) != 0)
        {
          data_done = true;
          sdmmc_ll_clear_interrupt(hw, SDMMC_LL_EVENT_DATA_OVER);
          sdmmc_dbg("TX DATA_OVER");
        }

      if ((idsts & SDMMC_LL_EVENT_DMA_TI) != 0)
        {
          dma_done = true;
          sdmmc_ll_clear_idsts_interrupt(hw, SDMMC_LL_EVENT_DMA_TI);
          sdmmc_dbg("TX DMA_TI");
        }

      if (data_done && dma_done)
        {
          break;
        }
    }

  if (!data_done || !dma_done)
    {
      sdmmc_err("TX DMA timeout: data_done=%d dma_done=%d remaining=0x%08lx",
                data_done, dma_done,
                (unsigned long)sdmmc_ll_get_interrupt_raw(hw));
      return -ETIMEDOUT;
    }

  sdmmc_dbg("sendsetup OK");
