/* ========================================================================
 * 初始化
 * ======================================================================== */

int esp32p4_sdmmc_initialize(int slot, int minor)
{
  struct esp32p4_sdmmc_state_s *state = &g_sdmmc_state[slot];
  struct sdio_dev_s *dev;
  sdmmc_dev_t *hw = SDMMC_LL_GET_HW(0);
  int ret;

  printf("[SDMMC] ===== esp32p4_sdmmc_initialize slot=%d minor=%d =====\n",
         slot, minor);

  if (state->initialized)
    {
      printf("[SDMMC] Already initialized\n");
      return OK;
    }

  memset(state, 0, sizeof(*state));
  state->slot = slot;

  nxsem_init(&state->sem, 0, 0);

  /* 1. LDO（Slot0 需要 1.8V/3.3V 电源） */
  printf("[SDMMC] Step 1: LDO init\n");
  if (slot == 0)
    {
      ret = esp32p4_sdmmc_ldo_init(state);
      if (ret < 0)
        {
          printf("[SDMMC ERROR] LDO init failed: %d\n", ret);
          goto err_ldo;
        }
    }

  /* 2. GPIO */
  printf("[SDMMC] Step 2: GPIO init\n");
  ret = esp32p4_sdmmc_gpio_init(state);
  if (ret < 0)
    {
      printf("[SDMMC ERROR] GPIO init failed: %d\n", ret);
      goto err_gpio;
    }

  /* 3. 使能 SDMMC 总线时钟（关键！必须在访问寄存器之前） */
  printf("[SDMMC] Step 3: Enable bus clock\n");
  sdmmc_ll_enable_bus_clock(0, true);

  /* 4. 复位 SDMMC 模块 */
  printf("[SDMMC] Step 4: Reset register\n");
  sdmmc_ll_reset_register(0);

  /* 5. 选择时钟源并设置分频 */
  printf("[SDMMC] Step 5: Clock source setup\n");
  sdmmc_ll_select_clk_source(hw, SDMMC_CLK_SRC_PLL160M);
  sdmmc_ll_set_clock_div(hw, 10);  /* 160MHz / 10 = 16MHz (for init) */
  sdmmc_ll_init_phase_delay(hw);

  /* 6. 控制器内部复位 */
  printf("[SDMMC] Step 6: Controller reset\n");
  esp32p4_sdmmc_reset_controller();

  /* 7. 超时配置 */
  printf("[SDMMC] Step 7: Timeout config\n");
  sdmmc_ll_set_data_timeout(hw, 0xFFFFFF);
  sdmmc_ll_set_response_timeout(hw, 0xFF);

  /* 8. 块大小 */
  printf("[SDMMC] Step 8: Block size\n");
  sdmmc_ll_set_block_size(hw, 512);

  /* 9. 使能 Card Clock */
  printf("[SDMMC] Step 9: Card clock enable\n");
  sdmmc_ll_enable_card_clock(hw, slot, true);

  /* 10. 初始化 DMA */
  printf("[SDMMC] Step 10: DMA init\n");
  sdmmc_ll_init_dma(hw);
  sdmmc_ll_enable_dma(hw, true);

  /* 11. 中断 */
  printf("[SDMMC] Step 11: Interrupt setup\n");
  state->cpuint = esp_setup_irq(ETS_SDIO_HOST_INTR_SOURCE,
                                ESP_IRQ_PRIORITY_DEFAULT,
                                ESP_IRQ_TRIGGER_LEVEL,
                                esp32p4_sdmmc_interrupt,
                                state);
  if (state->cpuint < 0)
    {
      ret = state->cpuint;
      printf("[SDMMC ERROR] IRQ setup failed: %d\n", ret);
      goto err_irq;
    }

  sdmmc_ll_enable_interrupt(hw, SDMMC_LL_EVENT_DEFAULT, true);
  sdmmc_ll_enable_global_interrupt(hw, true);

  /* 12. 设置初始时钟 400kHz（用于卡探测） */
  printf("[SDMMC] Step 12: Set init clock 400kHz\n");
  esp32p4_sdmmc_set_clock(state, 400);

  /* 13. 检测卡是否存在 */
  printf("[SDMMC] Step 13: Card detect\n");
  {
    bool detected = sdmmc_ll_is_card_detected(hw, slot);
    printf("[SDMMC] Card detected: %s (cdetect reg=0x%08lx)\n",
           detected ? "YES" : "NO",
           (unsigned long)hw->cdetect.val);

    /* 读取硬件版本和配置 */
    printf("[SDMMC] HW version: 0x%08lx\n",
           (unsigned long)sdmmc_ll_get_version_id(hw));
    printf("[SDMMC] HW config:  0x%08lx\n",
           (unsigned long)sdmmc_ll_get_hw_config_info(hw));

